    # a genuinely different basin than the start (which is a fine local optimum),
    # because low-res optimisation removes spurious high-frequency structure and
    # finds a smoother, better-conditioned shape; prolongating recovers detail.
    alt = None
    altR = 0.0
    N = best.size
    for factor in (4, 2):
        if time.process_time() >= deadline - 12.0:
            break
        Nc = max(256, N // factor)
        hc = _coarse(best, Nc)
        hc = _rescale(hc)
        # smooth to escape the fine local optimum
        hc = _gauss_smooth(hc, sigma=max(1.0, Nc / 400.0))
        hc = _rescale(hc)
        hc = _lbfgs_log(hc, 600, deadline)
        hc = _window_polish_peak(hc, deadline, 0.5, 8)
        hc = _lbfgs_log(hc, 400, deadline)
        r = R_of(hc)
        print("coarse %d R=%.7f" % (Nc, r))
        # prolongate back to full resolution and polish
        hp = _prolongate(hc, N)
        hp = _rescale(hp)
        hp = _lbfgs_log(hp, 500, deadline)
        hp = _window_polish_peak(hp, deadline, 0.4, 24)
        hp = _lbfgs_log(hp, 400, deadline)
        rp = R_of(hp)
        print("prolong %d->%d R=%.7f" % (Nc, N, rp))
        if alt is None or rp > altR:
            alt, altR = hp, rp

    if alt is not None and altR > bestR + 1e-15:
        best, bestR = alt, altR
        print("alt wins R=%.7f" % bestR)

    # Resolution sweep upward (may help if start was low-res).
    if time.process_time() < deadline - 8.0:
        for Nt in (int(N * 1.5), int(N * 2.0)):
            if Nt <= best.size:
                continue
            if Nt > 200000:
                Nt = 200000
            if time.process_time() >= deadline - 6.0:
                break
            hp = _prolongate(best, Nt)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 400, deadline)
            r = R_of(hp)
            print("grow %d -> R=%.7f" % (Nt, r))
            if r > bestR + 1e-15:
                best, bestR = hp, r
                N = best.size

    # Peak-focused multi-scale polish.
    for frac, extra in ((0.10, 4), (0.20, 8), (0.35, 16), (0.50, 32), (0.75, 64)):
        if time.process_time() >= deadline - 2.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra)
        h = _lbfgs_log(h, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("peak(%.2f) R=%.7f" % (frac, bestR))

    # Phase exploration around best.
    for delta in (-0.5, -0.25, 0.25, 0.5):
        if time.process_time() >= deadline - 2.0:
            break
        hp = _phase_shift(best, delta)
        hp = _rescale(hp)
        if hp.sum() <= 0:
            continue
        hp = _lbfgs_log(hp, 600, deadline)
        hp = _window_polish_peak(hp, deadline, 0.35, 16)
        r = R_of(hp)
        print("phase %+.2f R=%.7f" % (delta, r))
        if r > bestR + 1e-15:
            best, bestR = hp, r

    # Final loop: alternate full and peak polish until budget exhausted.
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.40, 24)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 2:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if alt is not None and altR <= R_of(np.asarray(start, dtype=float)) + 1e-15:
        return {"best": best, "alternative": alt}
    return best

