def _modulate(hc, P, eps):
    n = hc.size
    x = np.arange(n, dtype=float)
    factor = 1.0 + eps * np.cos(2.0 * np.pi * x / P)
    return np.clip(hc * factor, 0.0, None)


def _comb_add(hc, P, eps):
    n = hc.size
    mean = hc.mean() if hc.mean() > 0 else 1.0
    out = hc.copy()
    j = 0
    while j * P < n:
        idx = int(round(j * P))
        if 0 <= idx < n:
            out[idx] += eps * mean
        j += 1
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    print("base R=%.7f (N=%d)" % (bestR, best.size))

    N = best.size

    # Base behaviour: resolution sweep upward.
    if time.process_time() < deadline - 8.0:
        for Nt in (N, int(N * 1.5), int(N * 2.0)):
            if Nt <= best.size:
                continue
            if Nt > 200000:
                Nt = 200000
            if time.process_time() >= deadline - 6.0:
                break
            hp = _prolongate(best, Nt)
            hp = _rescale(hp)
            hp = _lbfgs_log(hp, 400, deadline)
            r = R_of(hp)
            print("grow %d -> R=%.7f" % (Nt, r))
            if r > bestR + 1e-15:
