    return np.clip(out, 0, None)


def _random_sparse_start(rng, N):
    B = int(rng.integers(12, 41))
    widths = np.exp(rng.uniform(np.log(1.0), np.log(60.0), size=B))
    widths = widths / widths.sum()
    heights = np.exp(rng.uniform(np.log(1.0), np.log(300.0), size=B))
    h = np.zeros(N)
    edges = np.concatenate(([0.0], np.cumsum(widths)))
    for i in range(B):
        lo = int(edges[i] * N)
        hi = int(edges[i + 1] * N)
        if hi <= lo:
            hi = lo + 1
        lo = min(lo, N - 1)
        hi = min(hi, N)
        h[lo:hi] = np.maximum(h[lo:hi], heights[i])
    # zero out 50-75% of entries (leave gaps)
    frac_zero = rng.uniform(0.5, 0.75)
    mask = rng.random(N) < frac_zero
    h[mask] = 0.0
    if h.sum() <= 0:
        h = np.ones(N)
    return _rescale(h)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(12345)

    # Phase 1: random sparse multiscale starts at N0=1024
    N0 = 1024
    n_starts = 24
    cands = []
    for i in range(n_starts):
        if time.process_time() >= deadline - 1.0:
            break
        h = _random_sparse_start(rng, N0)
        h = _lbfgs_log(h, maxiter=600, deadline=deadline)
        r = R_of(h)
        cands.append((r, h))
        if r > best_r:
            best, best_r = h.copy(), r

    cands.sort(key=lambda x: -x[0])
    top = [h for r, h in cands[:4]]
    if not top:
        top = [best.copy()]

    # Phase 2: ladder top candidates upward
    levels = [2048, 4096, 8192, 16384, 32000]
    pool = [(R_of(h), h) for h in top]
    for N in levels:
        if time.process_time() >= deadline - 1.0:
            break
        new_pool = []
        for r, h in pool:
            if time.process_time() >= deadline - 1.0:
                new_pool.append((r, h))
                continue
            cand = _prolongate(h, N)
            cand = _smooth_conv(cand, 2)
            cand = _rescale(cand)
            cand = _lbfgs_log(cand, maxiter=500, deadline=deadline)
            cand = _window_polish_peak(cand, deadline, 0.25, 16, maxiter=400)
            rr = R_of(cand)
            new_pool.append((rr, cand))
            if rr > best_r:
                best, best_r = cand.copy(), rr
        new_pool.sort(key=lambda x: -x[0])
        pool = new_pool[:4]

    cur = best.copy()
    cur_r = best_r

    # Phase 3: alternate full polish + peak window on best
    while time.process_time() < deadline - 0.5:
        cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.5:
            break
        cand = _window_polish_peak(cur, deadline, 0.10, 4, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        # also try a wider window occasionally
        if time.process_time() >= deadline - 0.5:
            break
        cand = _window_polish_peak(cur, deadline, 0.30, 8, maxiter=600)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r

    if start_arr is not None:
        rs = R_of(start_arr)
        if rs >= best_r:
            return {"best": best, "alternative": start_arr}
        else:
            return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarse(h, Nc):
    n = h.size
    if n == Nc:
        return h.copy()
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, Nc + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    hc = np.clip(np.diff(Sb), 0.0, None)
    if hc.sum() <= 0:
        return np.ones(Nc)
    return hc


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW PRIMARY IDEA: iterative "peak-flattening / support-tightening"
    # via a reweighted objective.  R = ||L||_2^2 / (||L||_1 * ||L||_inf).
    # The bottleneck is ||L||_inf: the peak of the autoconvolution.
    # We add a soft penalty pushing DOWN the peak region and lifting the rest,
    # which is exactly the regime where a small shape change gives a big R gain.
    # We do this by a "peak-reduction" step: solve a modified problem where
    # the max-knot is replaced by a soft-max (logsumexp over top knots),
    # whose gradient encourages flattening the top of the peak.
    def _fun_grad_soft(h, beta):
        s = h.sum()
        if s <= 0:
            return 1e18, np.zeros(h.size)
        num, dq, Lf = _num_and_dq(h)
        # soft-max over all knots: LSE = (1/beta) log sum exp(beta L)
        Lmax = Lf.max()
        e = np.exp(beta * (Lf - Lmax))
        Z = e.sum()
        softmax = e / Z
        Lse = Lmax + np.log(Z) / beta
        # gradient of Lse wrt Lf is softmax
        gLf = -dq / num + softmax / Lse
        grad = _backprop(gLf, h) + 2.0 / s
        val = -np.log(num) + 2.0 * np.log(s) + np.log(Lse)
        return val, grad

    def _lbfgs_soft(h0, beta, maxiter, dl):
        if time.process_time() >= dl - 0.3:
            return h0
        h = np.clip(h0, 0, None)
        if h.sum() <= 0:
            return h0
        n = h.size
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
        if active.size == 0:
            return h0
        u0 = np.log(np.clip(h[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = np.zeros(n)
            hh[active] = np.exp(uu)
            val, g = _fun_grad_soft(hh, beta)
            return val, g[active] * hh[active]

        cb = _make_cb(dl - 0.2)
        try:
            res = minimize(f, u0, jac=True, method='L-BFGS-B',
                           bounds=[(-30.0, 30.0)] * active.size,
                           callback=cb,
                           options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                    'ftol': 1e-20, 'gtol': 1e-16})
        except (TimeoutError, Exception):
            return h0
        if res is None:
            return h0
        h2 = np.zeros(n)
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale(h2)

    # Upsample start modestly (keep N manageable for soft-max which needs
    # many top knots), then run soft-max with increasing beta.
    N0 = best.size
    # Try several upsampled resolutions, pick best after soft polish.
    trials = []
    for mult in (1.0, 1.5, 2.0, 3.0):
        Nt = int(min(1000000, max(N0, N0 * mult)))
        if Nt not in trials:
            trials.append(Nt)

    best_overall = best.copy()
    best_overallR = bestR
    for Nt in trials:
        if time.process_time() >= deadline - 8.0:
            break
        cur = _up_resample(best, Nt) if Nt != best.size else best.copy()
        cur = _rescale(cur)
        # soft-max homotopy
        for beta in (30.0, 60.0, 120.0, 240.0, 480.0):
            if time.process_time() >= deadline - 6.0:
                break
            cur = _lbfgs_soft(cur, beta, 200, deadline)
        # finish with true objective
        cur = _lbfgs_log(cur, 400, deadline)
        r = R_of(cur)
        print("soft N=%d R=%.7f" % (Nt, r))
        if r > best_overallR + 1e-12:
            best_overall, best_overallR = cur, r

    # Now: local polish on the best we have with true objective, alternating
    # full-log and peak-window.
    best = best_overall
    bestR = best_overallR
    stall = 0
    while time.process_time() < deadline - 1.0:
        improved = False
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if time.process_time() >= deadline - 1.5:
            break
        h = _window_polish_peak(best, deadline, 0.45, 48, maxiter=400)
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            improved = True
        if not improved:
            stall += 1
            if stall >= 3:
                break
        else:
            stall = 0

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    if bestR > start_bestR - 1e-9 and best.size != start_best.size:
        # genuinely different shape, keep as alternative
        return {"best": start_best, "alternative": best}
    return {"best": start_best, "alternative": best}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_smooth(h, eps):
    """Smooth-min version: replace max by softmax over knots above a band."""
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = Lf.max()
    # weight knots near the max
    band = Lf > (m - eps * m)
    w = np.zeros_like(Lf)
    w[band] = np.exp((Lf[band] - m) / (eps * m + 1e-30))
    Z = w.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = w / Z
    # log of soft-max
    # soft-max = sum w_i L_i ; d/dh of log(softmax) = (1/softmax) * d softmax/dh
    softmax = np.dot(w, Lf)
    if softmax <= 0:
        return _fun_grad(h)
    # d softmax / dL = w (approx, ignoring w dependence on L)
    gLf = -dq / num + w / softmax
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(softmax)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, eps=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    fg = (lambda hh: _fun_grad_smooth(hh, eps)) if eps > 0 else _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, eps=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    fg = (lambda hh: _fun_grad_smooth(hh, eps)) if eps > 0 else _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, eps=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
