    if mask[-1]:
        ends = ends + [mask.size - 1]
    spikes = []
    for lo, hi in zip(starts, ends):
        mass = h[lo:hi + 1].sum()
        if mass <= 0:
            continue
        c = (lo + hi) // 2
        spikes.append([int(c), float(mass)])
