        N_big = min(20000, best.size * 2)
        h_big = _prolongate(best, N_big)
        sub_deadline = min(deadline - 0.5,
                           time.process_time() + (deadline - time.process_time()) * 0.5)
        cand = _lbfgs_log(h_big, maxiter=6000, deadline=sub_deadline)
        r = R_of(cand)
