def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _smooth(h, k):
    """Apply a small moving-average smoothing to escape sharp local features."""
    if k <= 1:
        return h
    ker = np.ones(k) / k
    hs = np.convolve(h, ker, mode='same')
    # keep edges reasonable
    return np.clip(hs, 0.0, None)


def _perturb(h, rng, scale):
    """Multiplicative random perturbation on active entries."""
    h2 = h.copy()
    nz = np.flatnonzero(h2 > 0)
    if nz.size == 0:
        return h2
    factors = np.exp(rng.normal(0.0, scale, nz.size))
    h2[nz] *= factors
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0
    rng = np.random.default_rng(12345)

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Track A: alternative resolution (coarsen then re-prolongate) as before
    alt = None
    alt_r = -1.0
    N_alt = 16384
    if cur.size >= N_alt and time.process_time() < deadline - 25.0:
        c = _rescale(_coarsen(cur, N_alt))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        c = _rescale(_prolongate(c, cur.size))
        c = _lbfgs_log(c, maxiter=400, deadline=deadline)
        alt = c
        alt_r = R_of(c)
        print("alt coarsen R = %.6f" % alt_r)

    # Smoothing continuation (shortened)
    for beta in (4, 16, 64):
        if time.process_time() >= deadline - 4.0:
            break
        c2 = _lbfgs_sm(cur, beta, maxiter=150, deadline=deadline)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        print("  beta=%d R=%.6f" % (beta, cur_r))

    # Main loop with a perturbation-restart mechanism
    restart_tries = 0
    no_improve = 0
    last_r = cur_r
    while time.process_time() < deadline - 1.0:
        # Standard full polish
        cand = _lbfgs_log(cur, maxiter=1200, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break

        # Peak window polish
        for frac, extra in ((0.05, 4), (0.15, 10)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

        # If not improving, try a gentle smoothing + re-polish to escape
        if cur_r <= last_r + 1e-9:
            no_improve += 1
            if no_improve >= 2 and time.process_time() < deadline - 3.0:
                k = 3 if restart_tries % 2 == 0 else 5
                seed = _rescale(_smooth(cur, k))
                seed = _lbfgs_log(seed, maxiter=800, deadline=deadline)
                rs = R_of(seed)
                if rs > cur_r:
                    cur, cur_r = seed, rs
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                    no_improve = 0
                else:
                    # perturbation restart from best
                    scale = 0.02 * (1 + restart_tries)
                    perturbed = _perturb(best, rng, min(scale, 0.2))
                    cand_p = _lbfgs_log(_rescale(perturbed), maxiter=1000,
                                        deadline=deadline)
                    rp = R_of(cand_p)
                    if rp > cur_r:
                        cur, cur_r = cand_p, rp
                        if cur_r > best_r:
                            best, best_r = cur.copy(), cur_r
                        no_improve = 0
                    else:
                        cur = best.copy(); cur_r = best_r
                restart_tries += 1
        else:
            no_improve = 0
        last_r = cur_r

    # Consider alternative if close
    if alt is not None and alt_r > best_r:
        best, best_r = alt.copy(), alt_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        # Return perturbation-restart result as alternative if it's genuinely new
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    if np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    if L.size == 0:
        return -1.0
    m = L.max()
    if m <= 0:
        return -1.0
    Lp = np.empty(L.size + 2, dtype=float)
    Lp[0] = 0.0
    Lp[1:-1] = L
    Lp[-1] = 0.0
    a = Lp[:-1]
    b = Lp[1:]
    sq = np.sum(a * a + a * b + b * b) / 3.0
    return sq / (s * s * m)


def _prolongate(h, N):
    n = h.size
    if n == N:
        return h.copy()
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _prolongate_mass(h, N):
    """Cumulative-mass (piecewise-constant) interpolation preserving integral."""
    n = h.size
    if n == N:
        return h.copy()
    # cumulative mass at edges
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    # new edges
    x_new = np.linspace(0.0, 1.0, N + 1)
    x_old = np.linspace(0.0, 1.0, n + 1)
    cm = np.interp(x_new, x_old, c)
    hn = np.diff(cm)
    hn = np.maximum(hn, 0.0)
    return hn


def _rescale(h):
    m = h.max()
    if m > 0:
        return h / m
    return h


def _lbfgs_log(h0, maxiter, deadline):
    from scipy.optimize import minimize
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-6)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def negR(x):
        h = np.exp(x)
        return -_R_of(h)

    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-12, 'gtol': 1e-10})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except Exception:
        pass
    return best_h, best_R


def _lbfgs_sm(h0, beta, maxiter, deadline):
    from scipy.optimize import minimize
    h0 = np.asarray(h0, dtype=float)
    if np.any(h0 <= 0):
        h0 = np.maximum(h0, 1e-6)
    best_h = h0.copy()
    best_R = _R_of(h0)
    x0 = np.log(h0)

    def negR(x):
        h = np.exp(x)
        s = h.sum()
        if s <= 0:
            return 1e10
        L = np.convolve(h, h)
        Lp = np.empty(L.size + 2, dtype=float)
        Lp[0] = 0.0
        Lp[1:-1] = L
        Lp[-1] = 0.0
        a = Lp[:-1]
        b = Lp[1:]
        sq = np.sum(a * a + a * b + b * b) / 3.0
        m = L.max()
        w = np.exp(beta * (L - m))
        sm = m + np.log(w.sum()) / beta
        return -(sq / (s * s * sm))

    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-12, 'gtol': 1e-10})
        h = np.exp(res.x)
        R = _R_of(h)
        if R > best_R:
            best_R = R
            best_h = h
    except Exception:
        pass
    return best_h, best_R


def _window_polish_peak(h, frac, extra, deadline):
    from scipy.optimize import minimize
    h = np.asarray(h, dtype=float)
    n = h.size
    if n < 8:
        return h, _R_of(h)
    L = np.convolve(h, h)
    peak = int(np.argmax(L))
    center = peak / 2.0
    half = max(2, int(frac * n))
    lo = max(0, int(center) - half)
    hi = min(n, int(center) + half + extra)
    if hi - lo < 4:
        return h, _R_of(h)
    best_h = h.copy()
    best_R = _R_of(h)
    sub = h[lo:hi].copy()
    if np.any(sub <= 0):
        sub = np.maximum(sub, 1e-6)
    x0 = np.log(sub)

    def negR(x):
        hh = h.copy()
        hh[lo:hi] = np.exp(x)
        return -_R_of(hh)

    try:
        res = minimize(negR, x0, method='L-BFGS-B',
                       options={'maxiter': 200, 'maxfun': 600,
                                'ftol': 1e-12, 'gtol': 1e-10})
        hh = h.copy()
        hh[lo:hi] = np.exp(res.x)
        R = _R_of(hh)
        if R > best_R:
            best_R = R
            best_h = hh
    except Exception:
        pass
    return best_h, best_R


def _polish_at_N(h, deadline, log_iters, sm_betas, sm_iters, windows):
    """Run log-LBFGS, softmax homotopy, and window polish at fixed N."""
    best_h = h.copy()
    best_R = _R_of(h)
    h, R = _lbfgs_log(h, log_iters, deadline)
    if R > best_R:
        best_R, best_h = R, h.copy()
    for beta in sm_betas:
        if time.process_time() > deadline:
            break
        h2, R2 = _lbfgs_sm(h, beta, sm_iters, deadline)
        if R2 > R:
            h, R = h2, R2
            if R > best_R:
                best_R, best_h = R, h.copy()
    for frac, extra in windows:
        if time.process_time() > deadline:
            break
        h2, R2 = _window_polish_peak(h, frac, extra, deadline)
        if R2 > R:
            h, R = h2, R2
            if R > best_R:
                best_R, best_h = R, h.copy()
    return best_h, best_R


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        if h.size == 0 or not np.all(np.isfinite(h)) or h.sum() <= 0:
            h = np.ones(64)
    else:
        h = np.ones(64)
    h = _rescale(np.maximum(h, 0))

    base_h = h.copy()
    base_R = _R_of(base_h)
    print("start R=%.6f N=%d" % (base_R, base_h.size))

    # If start is not already at N=512, bring it there.
    if base_h.size != 512:
        h512 = _prolongate_mass(base_h, 512)
    else:
        h512 = base_h.copy()
    h512 = _rescale(h512)
    R512 = _R_of(h512)
    if R512 > base_R:
        base_R = R512
        base_h = h512.copy()
    print("base at N=512 R=%.6f" % base_R)

    best_h = base_h.copy()
    best_R = base_R

    # Sharpening sweep at N=512
    sharp_results = {}
    for p in (2, 3, 4, 6, 8):
        if time.process_time() > deadline - 1.0:
            break
        hp = np.power(np.maximum(h512, 0.0), float(p))
        hp = _rescale(hp)
        if not np.all(np.isfinite(hp)) or hp.sum() <= 0:
            continue
        hh, RR = _polish_at_N(hp, deadline,
                              log_iters=300,
                              sm_betas=(4, 8, 16, 32),
                              sm_iters=150,
                              windows=((0.10, 8), (0.05, 4)))
        sharp_results[p] = RR
        print("p=%d R=%.6f" % (p, RR))
        if RR > best_R:
            best_R = RR
            best_h = hh.copy()

    print("best after sharpening R=%.6f" % best_R)

    # If sharpening improved on p0061 by >1e-4, extend to N=1024, 2048.
    if best_R > base_R + 1e-4:
        for N in (1024, 2048):
            if time.process_time() > deadline - 1.0:
                break
            hN = _prolongate_mass(best_h, N)
            hN = _rescale(hN)
            hh, RR = _polish_at_N(hN, deadline,
                                  log_iters=300,
                                  sm_betas=(8, 16, 32, 64),
                                  sm_iters=100,
                                  windows=((0.10, 8),))
            print("level N=%d R=%.6f best=%.6f" % (N, RR, max(RR, best_R)))
            if RR > best_R:
                best_R = RR
                best_h = hh.copy()

    # Use any remaining time to keep polishing best at its native N.
    while time.process_time() < deadline - 0.5:
        hh, RR = _lbfgs_log(best_h, 400, deadline)
        if RR > best_R:
            best_R = RR
            best_h = hh.copy()
        else:
            break
        hh, RR = _window_polish_peak(best_h, 0.10, 8, deadline)
        if RR > best_R:
            best_R = RR
            best_h = hh.copy()

    print("final R=%.6f N=%d" % (best_R, best_h.size))

    if start is not None:
        s = np.asarray(start, dtype=float)
        sR = _R_of(s)
        if sR >= best_R:
            return {"best": s, "alternative": best_h}
    return {"best": best_h, "alternative": best_h}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _random_seed(N0, rng):
    h = np.zeros(N0)
    K = int(rng.integers(6, 21))
    for _ in range(K):
        w = int(rng.integers(1, 9))
        pos = int(rng.integers(0, max(1, N0 - w)))
        ht = 10.0 ** rng.uniform(0.0, 2.5)
        h[pos:pos + w] = np.maximum(h[pos:pos + w], ht)
    if h.sum() <= 0:
        h[N0 // 2] = 1.0
    return h


def _ladder(h, deadline):
    """Prolongate stepwise through levels, polishing at each."""
    levels = [1024, 2048, 4096, 8192, 16384, 32768]
    cur = h
    cur_r = R_of(cur)
    for N in levels:
        if time.process_time() > deadline - 6.0:
            break
        if cur.size != N:
            cur = _rescale(_prolongate(cur, N))
        c = _lbfgs_log(cur, maxiter=350, deadline=deadline)
        if R_of(c) > cur_r:
            cur, cur_r = c, R_of(c)
        for beta in (8, 16, 32):
            if time.process_time() > deadline - 6.0:
                break
            c = _lbfgs_sm(cur, beta, maxiter=120, deadline=deadline)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        for frac, extra in ((0.10, 8), (0.05, 4)):
            if time.process_time() > deadline - 6.0:
                break
            c = _window_polish_peak(cur, deadline, frac, extra, maxiter=400)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        print("  level N=%d R=%.6f" % (cur.size, cur_r))
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))

    # ---- Multistart at coarse N0 = 512 ----
    N0 = 512
    rng = np.random.default_rng(12345)
    seeds = []
    for _ in range(12):
        seeds.append(_random_seed(N0, rng))
    if start_arr is not None:
        seeds.append(_rescale(_coarsen(start_arr, N0)))

    scored = []
    for i, sd in enumerate(seeds):
        if time.process_time() > deadline - 6.0:
            break
        cur = _rescale(sd)
        cur_r = R_of(cur)
        for beta in (2, 4, 8, 16):
            if time.process_time() > deadline - 6.0:
                break
            c = _lbfgs_sm(cur, beta, maxiter=150, deadline=deadline)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        if time.process_time() < deadline - 6.0:
            c = _lbfgs_log(cur, maxiter=300, deadline=deadline)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        scored.append((cur_r, i, cur))
        print("seed %d R=%.6f" % (i, cur_r))

    scored.sort(key=lambda t: -t[0])
    survivors = scored[:2]
    print("survivors: " + ", ".join("%.6f" % s[0] for s in survivors))

    for sr, si, sh in survivors:
        if time.process_time() > deadline - 6.0:
            break
        print("track from seed %d (R=%.6f)" % (si, sr))
        cur, cur_r = _ladder(sh, deadline)
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  new best R=%.6f" % best_r)

    # ---- Fallback: polish start if nothing beat it ----
    if start_arr is not None and best_r <= R_of(start_arr) + 1e-6:
        if time.process_time() < deadline - 1.0:
            cur = _rescale(start_arr.copy())
            cur_r = R_of(cur)
            while time.process_time() < deadline - 1.0:
                c = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
                r = R_of(c)
                if r > cur_r:
                    cur, cur_r = c, r
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
                if time.process_time() >= deadline - 1.0:
                    break
                for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
                    if time.process_time() >= deadline - 1.0:
                        break
                    c = _window_polish_peak(cur, deadline, frac, extra, maxiter=600)
                    r = R_of(c)
                    if r > cur_r:
                        cur, cur_r = c, r
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs(h0, fun, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    n = h.size
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fun(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_log(h0, maxiter, deadline):
    return _lbfgs(h0, _fun_grad, maxiter, deadline)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    return _lbfgs(h0, lambda h: _fun_grad_sm(h, beta), maxiter, deadline)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _multiscale_polish(h, deadline, best_r, best):
    """Coarsen, optimize at coarse scale, prolongate back, re-optimize."""
    n = h.size
    for N_c in (4096, 8192, 16384):
        if N_c >= n or time.process_time() >= deadline - 5.0:
            continue
        c = _rescale(_coarsen(h, N_c))
        c = _lbfgs_sm(c, 64, maxiter=300, deadline=deadline)
        c = _lbfgs_log(c, maxiter=600, deadline=deadline)
        c = _rescale(_prolongate(c, n))
        c = _lbfgs_log(c, maxiter=600, deadline=deadline)
        r = R_of(c)
        if r > best_r:
            best_r = r
            best = c.copy()
        if time.process_time() >= deadline - 2.0:
            break
    return best, best_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        # Seed with a smooth bump then refine
        N = 2048
        x = np.linspace(0, 1, N)
        best = np.exp(-((x - 0.5) ** 2) / 0.02) + 0.01
        best = _rescale(best)
        best_r = R_of(best)

    cur = _rescale(best.copy())
    cur_r = R_of(cur)
    if cur_r > best_r:
        best, best_r = cur.copy(), cur_r

    print("start R = %.6f, N = %d" % (cur_r, cur.size))

    # Smoothing continuation
    for beta in (2, 4, 8, 16, 32, 64):
        if time.process_time() >= deadline - 8.0:
            break
        c2 = _lbfgs_sm(cur, beta, maxiter=250, deadline=deadline)
        r2 = R_of(c2)
        if r2 > cur_r:
            cur, cur_r = c2, r2
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Main polish loop
    while time.process_time() < deadline - 1.0:
        cand = _lbfgs_log(cur, maxiter=2000, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 1.0:
            break
        for frac, extra in ((0.03, 4), (0.08, 8), (0.15, 16), (0.30, 32)):
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, frac, extra, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    # Multiscale escape: try coarsen/prolongate cycles if time remains
    if time.process_time() < deadline - 8.0:
        b2, r2 = _multiscale_polish(cur, deadline, best_r, best)
        if r2 > best_r:
            best, best_r = b2, r2
            cur, cur_r = b2.copy(), r2
        # continue polishing from improved point
        while time.process_time() < deadline - 1.0:
            cand = _lbfgs_log(cur, maxiter=1500, deadline=deadline)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
            if time.process_time() >= deadline - 1.0:
                break
            cand = _window_polish_peak(cur, deadline, 0.10, 8, maxiter=500)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

