def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    startR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    alt = None
    altR = 0.0

    def try_improve(h, tag):
        nonlocal best, bestR, alt, altR
        r = R_of(h)
        if r > bestR + 1e-15:
            best, bestR = h, r
            print("%s R=%.7f" % (tag, bestR))
            return True
        else:
            if alt is None or r > altR:
                alt, altR = h, r
            return False

    # --- Experiment: perturbed left-window restarts with smooth-max polish ---
    rng = np.random.default_rng(12345)
    betas = (5e4, 2e5, 5e5, 1e6)
    n_seeds = 12
    for seed in range(n_seeds):
        if time.process_time() >= deadline - 4.0:
