def _num_dq_Lf(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_dq_Lf(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_dq_Lf(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _run_lbfgs(f, x0, bounds, maxiter, deadline):
    cb = _make_cb(deadline)
    try:
        return minimize(f, x0, jac=True, method='L-BFGS-B',
                        bounds=bounds, callback=cb,
                        options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                 'ftol': 1e-22, 'gtol': 1e-18, 'maxcor': 20})
    except Exception:
        return None


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.25:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    res = _run_lbfgs(f, u0, [(-30.0, 30.0)] * active.size, maxiter, deadline - 0.15)
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.25:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    res = _run_lbfgs(f, u0, [(-30.0, 30.0)] * active.size, maxiter, deadline - 0.15)
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, logspace=False):
    if time.process_time() >= deadline - 0.25:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0

    if logspace:
        x0 = np.log(np.clip(h[active], 1e-300, None))

        def f(u):
            uu = np.clip(u, -30.0, 30.0)
            hh = h.copy()
            hh[active] = np.exp(uu)
            val, g = _fun_grad(hh)
            return val, g[active] * hh[active]

        res = _run_lbfgs(f, x0, [(-30.0, 30.0)] * active.size, maxiter, deadline - 0.15)
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
        return _rescale(h2)
    else:
        x0 = h[active].copy()

        def f(x):
            hh = h.copy()
            hh[active] = np.clip(x, 0.0, None)
            val, g = _fun_grad(hh)
            return val, g[active]

        res = _run_lbfgs(f, x0, [(0.0, None)] * active.size, maxiter, deadline - 0.15)
        if res is None:
            return h0
        h2 = h.copy()
        h2[active] = np.clip(res.x, 0.0, None)
        return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, logspace=False):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, logspace=logspace)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _coarsen(h_big, N_small):
    n = h_big.size
    if n == N_small:
        return h_big.copy()
    S = np.concatenate(([0.0], np.cumsum(h_big)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_small + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_small)
    return h


def _polish(h, deadline, budget_sub):
    cur = _rescale(np.asarray(h, dtype=float))
    cur_r = R_of(cur)
    t_end = min(deadline - 0.5, time.process_time() + budget_sub)

    for _ in range(3):
        if time.process_time() >= t_end:
            break
        c = _lbfgs_log(cur, maxiter=800, deadline=t_end)
        r = R_of(c)
        if r > cur_r:
            cur, cur_r = c, r
        for beta in (32, 64, 128):
            if time.process_time() >= t_end:
                break
            c = _lbfgs_sm(cur, beta, maxiter=400, deadline=t_end)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        for frac, extra in ((0.05, 4), (0.10, 8), (0.20, 16)):
            if time.process_time() >= t_end:
                break
            c = _window_polish_peak(cur, t_end, frac, extra, maxiter=600, logspace=False)
            r = R_of(c)
            if r > cur_r:
                cur, cur_r = c, r
        if time.process_time() >= t_end:
            break
    return cur, cur_r


# ---------- main ----------

def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    best = None
    best_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    print("start R = %.6f, N = %d" % (best_r, best.size))

    # Strategy: coarsen to a lower resolution first (cheaper, smoother landscape),
    # optimise there, then prolongate back up and re-polish. This escapes local
    # optima that block direct polish at N = 32768.
    if start_arr is not None and start_arr.size >= 64:
        # Try a few coarsening levels, building up from the smallest.
        levels = []
        n = start_arr.size
        for _ in range(4):
            n = max(64, n // 2)
            levels.append(n)
        levels = sorted(set(levels))
        seed = _rescale(best.copy())
        for N in levels:
            if time.process_time() > deadline - 6.0:
                break
            small = _rescale(_coarsen(seed, N)) if seed.size != N else seed
            # more polish budget for the smallest levels
            frac = 0.30 if N <= 256 else 0.20
            sub = max(1.0, (deadline - time.process_time()) * frac)
            small, sr = _polish(small, deadline, budget_sub=sub)
            # prolongate a bit farther than the next level to allow growth
            up = _rescale(_prolongate(small, min(start_arr.size, max(N * 2, N + 32))))
            up, ur = _polish(up, deadline, budget_sub=max(1.0,
                            (deadline - time.process_time()) * 0.20))
            seed = up
            if ur > best_r:
                # only accept as best if same N as start; otherwise it's an
                # intermediate seed. But still track it if bigger.
                pass
            print("  coarsen/grow N=%d -> R=%.6f" % (up.size, ur))

        # Final: bring up to start's N and polish.
        if seed.size != start_arr.size:
            seed = _rescale(_prolongate(seed, start_arr.size))
        cur, cur_r = _polish(seed, deadline,
                             budget_sub=max(1.0, deadline - time.process_time() - 0.5))
        if cur_r > best_r and cur.size == start_arr.size:
            best, best_r = cur.copy(), cur_r
            print("  coarsen pipeline -> R=%.6f" % best_r)
        elif cur_r > best_r:
            # different N but higher R: keep it (scoring allows any N)
            best, best_r = cur.copy(), cur_r
            print("  coarsen pipeline (N=%d) -> R=%.6f" % (cur.size, best_r))

    # Direct polish of start as fallback / final
    if time.process_time() < deadline - 1.0:
        cur, cur_r = _polish(best.copy(), deadline,
                             budget_sub=max(1.0, deadline - time.process_time() - 0.5))
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
            print("  final polish -> R=%.6f" % best_r)

    print("final R = %.6f, N = %d" % (best_r, best.size))

    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
