            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _refine_best(h, deadline, time_slice):
    cur = h.copy()
    cur_r = R_of(cur)
    t_end = min(deadline, time.process_time() + time_slice)
    while time.process_time() < t_end - 0.5:
        cand = _window_polish_peak(cur, t_end, 0.15, 8, maxiter=400, beta=400.0)
        cand = _lbfgs_log(cand, maxiter=500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _lbfgs_log(cur, maxiter=1500, deadline=t_end)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if time.process_time() >= t_end - 0.5:
            break
        cand = _window_polish_peak(cur, t_end, 0.4, 16, maxiter=500)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    best = None
    best_r = -1.0
    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            best = s.copy()
            best_r = R_of(best)

    if best is None:
        best = np.ones(50)
        best_r = R_of(best)

    rng = np.random.default_rng(98765)

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        cur, cur_r = _refine_best(cur, deadline, min(20.0, deadline - time.process_time() - 0.5))
        return cur

    cur = start_arr.copy()
    cur_r = best_r
    alternative = None
    alt_r = -1.0

    n_full = cur.size
    if n_full >= 4000:
        N_smalls = [max(1000, n_full // 8), max(1000, n_full // 4), max(1000, n_full // 2)]
    elif n_full >= 1500:
        N_smalls = [max(500, n_full // 3), max(500, n_full // 2)]
    else:
        N_smalls = [n_full]

    did_coarse = 0
    coarse_idx = 0

    while time.process_time() < deadline - 0.8:
        for beta in (200.0, 600.0, 1500.0):
            if time.process_time() >= deadline - 0.8:
                break
            cand = _lbfgs_sm(cur, beta, maxiter=300, deadline=deadline - 0.5)
            r = R_of(cand)
            if r > cur_r:
                cur, cur_r = cand, r
        cand = _lbfgs_log(cur, maxiter=800, deadline=deadline - 0.5)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        cand = _window_polish_peak(cur, deadline - 0.5, 0.4, 20, maxiter=500, beta=800.0)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
        if cur_r > best_r:
            best, best_r = cur.copy(), cur_r
        if time.process_time() >= deadline - 0.8:
            break

        # NEW: also try to grow the resolution upward and re-polish, which
        # sometimes finds structure the current N cannot represent.
        if n_full <= 200000 and time.process_time() < deadline - 5.0 and rng.random() < 0.35:
            N_up = min(1000000, n_full * 2)
            h_up = _prolongate(cur, N_up)
            slice_end = min(deadline - 0.5, time.process_time() + 3.5)
            h_up = _lbfgs_log(h_up, maxiter=600, deadline=slice_end)
            h_up = _window_polish_peak(h_up, slice_end, 0.3, 16, maxiter=400, beta=600.0)
            h_up = _lbfgs_log(h_up, maxiter=400, deadline=slice_end)
            r = R_of(h_up)
            if r > cur_r:
                cur, cur_r = h_up, r
                n_full = N_up
                if cur_r > best_r:
                    best, best_r = cur.copy(), cur_r
            elif r > alt_r:
                alternative, alt_r = h_up.copy(), r

        do_coarse = (did_coarse < len(N_smalls)) or (rng.random() < 0.4)
        if do_coarse and time.process_time() < deadline - 4.0:
            N_small = N_smalls[coarse_idx % len(N_smalls)]
            coarse_idx += 1
            if N_small < n_full:
                did_coarse += 1
                h_small = _prolongate(cur, N_small)
                slice_end = min(deadline - 0.5, time.process_time() + 3.5)
                for beta in (300.0, 1000.0):
                    if time.process_time() >= slice_end - 0.5:
                        break
                    h_small = _lbfgs_sm(h_small, beta, maxiter=200, deadline=slice_end)
                h_small = _lbfgs_log(h_small, maxiter=400, deadline=slice_end)
                h_big = _prolongate(h_small, n_full)
                h_big = _lbfgs_log(h_big, maxiter=600, deadline=deadline - 0.5)
                h_big = _window_polish_peak(h_big, deadline - 0.5, 0.3, 16,
                                            maxiter=400, beta=600.0)
                r = R_of(h_big)
                if r > cur_r:
                    cur, cur_r = h_big, r
                    if cur_r > best_r:
                        best, best_r = cur.copy(), cur_r
                elif r > alt_r:
                    alternative, alt_r = h_big.copy(), r
        if time.process_time() >= deadline - 0.8:
            break

        n = cur.size
        trial = cur.copy()
        blk = int(rng.integers(max(4, n // 25), max(8, n // 6)))
        lo = int(rng.integers(0, max(1, n - blk)))
        hi = min(n, lo + blk)
        noise = np.exp(rng.normal(0.0, 0.3, size=hi - lo))
        trial[lo:hi] = np.clip(trial[lo:hi] * noise, 0, None)
        trial = _rescale(trial)
        trial_r = R_of(trial)
        if trial_r > 0.7 * cur_r:
            trial, trial_r = _refine_best(trial, deadline - 0.5,
                                          time_slice=min(6.0, deadline - time.process_time() - 0.5))
        if trial_r > cur_r:
            cur, cur_r = trial, trial_r
            if cur_r > best_r:
                best, best_r = cur.copy(), cur_r
        elif trial_r > alt_r:
            alternative, alt_r = trial.copy(), trial_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num + w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.4:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = (_fun_grad(hh) if beta is None else _fun_grad_sm(hh, beta))
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.4:
        return h0
