        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=1200, deadline=deadline))
    for beta in (400.0, 1500.0, 4000.0):
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=300, deadline=deadline))
    if time.process_time() < deadline - 0.5:
