        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _prolongate(h, M):
    """Cumulative-mass resample: each new height = mass of old interval it covers * M/N_old."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _restrict(h, M):
    """Cumulative-mass resample to coarser grid (M < N)."""
    return _prolongate(h, M)


def _polish_chain(h, deadline, log_iters, sm_betas, sm_iters, polish_fracs,
                  polish_extra, polish_iters):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for beta in sm_betas:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=sm_iters, deadline=deadline))
    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for frac in polish_fracs:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_window_polish_peak(cur, deadline, frac, polish_extra,
                                 maxiter=polish_iters, beta=None))
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ---------------- Strategy A: prolongation to finer grids --------------
    accepted_64 = None
    if time.process_time() < hard_end - 2.0:
        h64 = _prolongate(base, 64000)
        h64, r64 = _polish_chain(
            h64, hard_end,
            log_iters=1200,
            sm_betas=(400.0, 1500.0, 4000.0),
            sm_iters=300,
            polish_fracs=(0.05, 0.10, 0.20),
            polish_extra=8,
            polish_iters=400,
        )
        print("prolong 64000 R=%.6f (base %.6f)" % (r64, base_r))
        if r64 > base_r:
            accepted_64 = h64
            _consider(h64, r64)
        else:
            n = h64.size
            for seed in range(6):
                if time.process_time() >= hard_end - 2.0:
                    break
                rng = np.random.default_rng(7000 + seed)
                lo = int(rng.uniform(0.0, 0.35) * n)
                hi = min(n, lo + n // 2)
                hp = _perturb_window_at(h64, lo, hi, rng, sigma=0.30)
                hp, rp = _polish_chain(
                    hp, hard_end,
                    log_iters=1200,
                    sm_betas=(400.0, 1500.0, 4000.0),
                    sm_iters=300,
                    polish_fracs=(0.05, 0.10, 0.20),
                    polish_extra=8,
                    polish_iters=400,
                )
                print("  perturb seed %d R=%.6f" % (seed, rp))
                _consider(hp, rp)
                if rp > base_r and (accepted_64 is None or rp > R_of(accepted_64)):
                    accepted_64 = hp

    if accepted_64 is not None and time.process_time() < hard_end - 2.0:
        h128 = _prolongate(accepted_64, 128000)
        h128, r128 = _polish_chain(
            h128, hard_end,
            log_iters=1200,
            sm_betas=(400.0, 1500.0, 4000.0),
            sm_iters=300,
            polish_fracs=(0.05, 0.10, 0.20),
            polish_extra=8,
            polish_iters=600,
        )
        print("prolong 128000 R=%.6f" % r128)
        if r128 > base_r:
            _consider(h128, r128)

    print("experiment R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    # ---------------- Strategy B: RESTRICTION to coarser grid --------------
    # A coarser grid has fewer DOF; optimizing it exactly can push into a
    # better basin, then we prolongate back and re-polish.  This is the new
    # idea: coarse->fine cycle at N=16000 / 8000 / 4000.
    if time.process_time() < hard_end - 3.0:
        for Nc in (16000, 8000, 4000):
            if time.process_time() >= hard_end - 2.5:
                break
            hc = _restrict(best, Nc)
            hc, rc = _polish_chain(
                hc, hard_end,
                log_iters=1500,
                sm_betas=(600.0, 2000.0, 6000.0),
                sm_iters=400,
                polish_fracs=(0.10, 0.20, 0.35),
                polish_extra=6,
                polish_iters=500,
            )
            print("restrict N=%d R=%.6f" % (Nc, rc))
            _consider(hc, rc)
            if rc > base_r:
                # prolongate back to a finer grid and re-polish
                for Nf in (Nc * 2, min(Nc * 4, 64000)):
                    if time.process_time() >= hard_end - 2.0:
                        break
                    hf = _prolongate(hc, Nf)
                    hf, rf = _polish_chain(
                        hf, hard_end,
                        log_iters=1200,
                        sm_betas=(400.0, 1500.0, 4000.0),
                        sm_iters=300,
                        polish_fracs=(0.05, 0.10, 0.20),
                        polish_extra=8,
                        polish_iters=400,
                    )
                    print("  coarse->fine N=%d R=%.6f" % (Nf, rf))
                    _consider(hf, rf)

    # ---------------- Fallback: polish current best until deadline ----------
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    return float(sq / (s * s * m))


def _knots(h):
    L = fftconvolve(h, h)
    n = h.size
    L = L[:2 * n - 1]
    return np.concatenate(([0.0], L, [0.0]))


def _num_and_dq(L):
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq


def _backprop(gLf, h):
    n = h.size
    return 2.0 * fftconvolve(gLf[1:-1], h[::-1], mode='valid')[:n]


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _adaptive_resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    hmax = h.max()
    if hmax <= 0:
        return np.ones(N)
    w = h * h + 1e-6 * (hmax * hmax)
    c = np.concatenate(([0.0], np.cumsum(w)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    t = np.linspace(0.0, total, N + 1)
    x = np.interp(t, c, np.arange(M + 1, dtype=float))
    cm = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.arange(M + 1, dtype=float)
    vals = np.interp(x, xs, cm)
    dx = np.diff(x)
    dx = np.where(dx <= 1e-15, 1e-15, dx)
    out = np.diff(vals) / dx
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N)
    return out


def _lbfgs_log(h, maxiter, deadline):
    n = h.size
    x0 = np.log(np.maximum(h, 1e-12))
    mask = h > 1e-13 * h.max()
    if mask.sum() < 2:
        mask = np.ones(n, dtype=bool)

    def fun(x):
        hh = np.zeros(n)
        hh[mask] = np.exp(np.clip(x, -50, 50))
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        L = _knots(hh)
        num, dq = _num_and_dq(L)
        m = L.max()
        if m <= 0 or num <= 0:
            return 1e30, np.zeros_like(x)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
        gL = -dq / num
        k = np.argmax(L)
        gL[k] += 1.0 / m
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[mask] * hh[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.zeros(n)
        out[mask] = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _lbfgs_sm(h, beta, maxiter, deadline):
    n = h.size
    x0 = np.log(np.maximum(h, 1e-12))
    mask = h > 1e-13 * h.max()
    if mask.sum() < 2:
        mask = np.ones(n, dtype=bool)

    def fun(x):
        hh = np.zeros(n)
        hh[mask] = np.exp(np.clip(x, -50, 50))
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        L = _knots(hh)
        num, dq = _num_and_dq(L)
        if num <= 0:
            return 1e30, np.zeros_like(x)
        M = L.max()
        e = np.exp(beta * (L - M))
        Z = e.sum()
        lse = M + np.log(Z) / beta
        val = -np.log(num) + 2.0 * np.log(s) + lse
        w = e / Z
        gL = -dq / num + w
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[mask] * hh[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.zeros(n)
        out[mask] = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _window_polish_peak(h, frac, extra, maxiter, deadline):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    L = _knots(h)
    k = int(np.argmax(L))
    half = max(2, int(frac * n))
    lo = max(0, (k - half) // 2 - extra)
    hi = min(n, (k + half) // 2 + extra + 1)
    if hi - lo < 2:
        return h
    sub = h[lo:hi].copy()
    m = sub.size
    x0 = np.log(np.maximum(sub, 1e-12))
    mask = sub > 1e-13 * sub.max()
    if mask.sum() < 2:
        mask = np.ones(m, dtype=bool)

    def fun(x):
        hh = h.copy()
        s2 = np.zeros(m)
        s2[mask] = np.exp(np.clip(x, -50, 50))
        hh[lo:hi] = s2
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        Lp = _knots(hh)
        num, dq = _num_and_dq(Lp)
        mm = Lp.max()
        if mm <= 0 or num <= 0:
            return 1e30, np.zeros_like(x)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(mm)
        gL = -dq / num
        kk = np.argmax(Lp)
        gL[kk] += 1.0 / mm
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[lo:hi][mask] * s2[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = h.copy()
        s2 = np.zeros(m)
        s2[mask] = np.exp(np.clip(res.x, -50, 50))
        out[lo:hi] = s2
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = _R_of(best)

    base = best.copy()
    baseR = bestR

    def try_accept(cand):
        nonlocal best, bestR
        rc = _R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    # --- Adaptive mass-weighted resample to N=64000 ---
    N = 64000
    adaptive_ok = False
    if time_left():
        had = _adaptive_resample(base, N)
        if had.sum() > 0 and np.all(np.isfinite(had)):
            h = had
            if time_left():
                c = _lbfgs_log(h, 1500, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            for beta in (200, 1000, 5000, 20000):
                if not time_left():
                    break
                c = _lbfgs_sm(h, beta, 300, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            if time_left():
                c = _lbfgs_log(h, 1000, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            for f in (0.05, 0.10, 0.20):
                if not time_left():
                    break
                c = _window_polish_peak(h, f, 8, 400, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            if try_accept(h):
                adaptive_ok = True

    # --- If adaptive failed, fall back to base's own pipeline ---
    if not adaptive_ok:
        h = base.copy()
        levels = (8000, 32000, 64000)
        for li, Nl in enumerate(levels):
            if not time_left():
                break
            h = _prolongate(h, Nl)
            try_accept(h)
            it_log = 1500 if li == 0 else 800
            it_sm = 400 if li == 0 else 250
            it_pol = 400 if li == 0 else 250
            if time_left():
                c = _lbfgs_log(h, it_log, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
                try_accept(h)
            for beta in (100, 500, 2000):
                if not time_left():
                    break
                c = _lbfgs_sm(h, beta, it_sm, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
                try_accept(h)
            if time_left():
                c = _lbfgs_log(h, it_log, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
                try_accept(h)
            for f in (0.10, 0.25, 0.40):
                if not time_left():
                    break
                c = _window_polish_peak(h, f, 8, it_pol, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
                try_accept(h)

    # --- Final polishing loop on best ---
    fracs = (0.05, 0.10, 0.20, 0.15)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, 500, deadline)
        try_accept(c)
        if not time_left():
            break
        f = fracs[fi % len(fracs)]
        fi += 1
        c = _window_polish_peak(best, f, 8, 300, deadline)
        try_accept(c)

    # Return best; if adaptive produced a distinct construction that lost, offer as alternative
    if adaptive_ok:
        return best
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _prolongate(h, M):
    """Cumulative-mass resample: each new height = mass of old interval it covers * M/N_old."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _downsample(h, M):
    """Cumulative-mass downsample: new height = mass covered / (N/M)."""
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at) * (M / N)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _polish_chain(h, deadline, log_iters, sm_betas, sm_iters, polish_fracs,
                  polish_extra, polish_iters):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for beta in sm_betas:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=sm_iters, deadline=deadline))
    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for frac in polish_fracs:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_window_polish_peak(cur, deadline, frac, polish_extra,
                                 maxiter=polish_iters, beta=None))
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ---------------- Experiment: coarse re-optimisation + regrow ----------
    # (1) Downsample base to N=16000
    h16 = None
    if time.process_time() < hard_end - 2.0:
        h16 = _downsample(base, 16000)
        print("downsample 16000 R=%.6f (base %.6f)" % (R_of(h16), base_r))

    # (2) Coarse polish: exact log 2000, softmax 200/800/3000 (400), exact log 1200
    h16_best = None
    if h16 is not None and time.process_time() < hard_end - 2.0:
        h16_best, r16 = _polish_chain(
            h16, hard_end,
            log_iters=2000,
            sm_betas=(200.0, 800.0, 3000.0),
            sm_iters=400,
            polish_fracs=(),
            polish_extra=0,
            polish_iters=0,
        )
        # extra exact log pass
        if time.process_time() < hard_end - 1.0:
            c = _lbfgs_log(h16_best, maxiter=1200, deadline=hard_end)
            if R_of(c) > r16:
                h16_best, r16 = c, R_of(c)
        print("coarse 16000 R=%.6f" % r16)

    # (3) Prolongate back to N=64000 and fine polish
    if h16_best is not None and time.process_time() < hard_end - 2.0:
        h64 = _prolongate(h16_best, 64000)
        h64, r64 = _polish_chain(
            h64, hard_end,
            log_iters=1200,
            sm_betas=(400.0, 1500.0, 4000.0),
            sm_iters=300,
            polish_fracs=(0.05, 0.10, 0.20),
            polish_extra=8,
            polish_iters=400,
        )
        print("regrow 64000 R=%.6f" % r64)
        if r64 > base_r:
            _consider(h64, r64)

    print("experiment R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    # ---------------- Fallback: base-style refinement if time remains ------
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
