import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _R_of(h):
    h = np.asarray(h, dtype=float)
    if h.ndim != 1 or h.size == 0:
        return -1.0
    if not np.all(np.isfinite(h)) or np.any(h < 0):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    L = np.concatenate(([0.0], L, [0.0]))
    m = L.max()
    if m <= 0:
        return -1.0
    sq = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    return float(sq / (s * s * m))


def _knots(h):
    L = fftconvolve(h, h)
    n = h.size
    L = L[:2 * n - 1]
    return np.concatenate(([0.0], L, [0.0]))


def _num_and_dq(L):
    a = L[:-1]
    b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(L)
    dq[:-1] += (2.0 * a + b) / 3.0
    dq[1:] += (a + 2.0 * b) / 3.0
    return num, dq


def _backprop(gLf, h):
    n = h.size
    return 2.0 * fftconvolve(gLf[1:-1], h[::-1], mode='valid')[:n]


def _prolongate(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _adaptive_resample(h, N):
    h = np.asarray(h, dtype=float)
    M = h.size
    hmax = h.max()
    if hmax <= 0:
        return np.ones(N)
    w = h * h + 1e-6 * (hmax * hmax)
    c = np.concatenate(([0.0], np.cumsum(w)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    t = np.linspace(0.0, total, N + 1)
    x = np.interp(t, c, np.arange(M + 1, dtype=float))
    cm = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.arange(M + 1, dtype=float)
    vals = np.interp(x, xs, cm)
    dx = np.diff(x)
    dx = np.where(dx <= 1e-15, 1e-15, dx)
    out = np.diff(vals) / dx
    out = np.maximum(out, 0.0)
    if out.sum() <= 0:
        return np.ones(N)
    return out


def _lbfgs_log(h, maxiter, deadline):
    n = h.size
    x0 = np.log(np.maximum(h, 1e-12))
    mask = h > 1e-13 * h.max()
    if mask.sum() < 2:
        mask = np.ones(n, dtype=bool)

    def fun(x):
        hh = np.zeros(n)
        hh[mask] = np.exp(np.clip(x, -50, 50))
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        L = _knots(hh)
        num, dq = _num_and_dq(L)
        m = L.max()
        if m <= 0 or num <= 0:
            return 1e30, np.zeros_like(x)
        val = -np.log(num) + 2.0 * np.log(s) + np.log(m)
        gL = -dq / num
        k = np.argmax(L)
        gL[k] += 1.0 / m
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[mask] * hh[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.zeros(n)
        out[mask] = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _lbfgs_sm(h, beta, maxiter, deadline):
    n = h.size
    x0 = np.log(np.maximum(h, 1e-12))
    mask = h > 1e-13 * h.max()
    if mask.sum() < 2:
        mask = np.ones(n, dtype=bool)

    def fun(x):
        hh = np.zeros(n)
        hh[mask] = np.exp(np.clip(x, -50, 50))
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        L = _knots(hh)
        num, dq = _num_and_dq(L)
        if num <= 0:
            return 1e30, np.zeros_like(x)
        M = L.max()
        e = np.exp(beta * (L - M))
        Z = e.sum()
        lse = M + np.log(Z) / beta
        val = -np.log(num) + 2.0 * np.log(s) + lse
        w = e / Z
        gL = -dq / num + w
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[mask] * hh[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = np.zeros(n)
        out[mask] = np.exp(np.clip(res.x, -50, 50))
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _window_polish_peak(h, frac, extra, maxiter, deadline, beta=None):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    L = _knots(h)
    k = int(np.argmax(L))
    half = max(2, int(frac * n))
    lo = max(0, (k - half) // 2 - extra)
    hi = min(n, (k + half) // 2 + extra + 1)
    if hi - lo < 2:
        return h
    sub = h[lo:hi].copy()
    m = sub.size
    x0 = np.log(np.maximum(sub, 1e-12))
    mask = sub > 1e-13 * sub.max()
    if mask.sum() < 2:
        mask = np.ones(m, dtype=bool)

    def fun(x):
        hh = h.copy()
        s2 = np.zeros(m)
        s2[mask] = np.exp(np.clip(x, -50, 50))
        hh[lo:hi] = s2
        s = hh.sum()
        if s <= 0:
            return 1e30, np.zeros_like(x)
        Lp = _knots(hh)
        num, dq = _num_and_dq(Lp)
        mm = Lp.max()
        if mm <= 0 or num <= 0:
            return 1e30, np.zeros_like(x)
        if beta is None:
            val = -np.log(num) + 2.0 * np.log(s) + np.log(mm)
            gL = -dq / num
            kk = np.argmax(Lp)
            gL[kk] += 1.0 / mm
        else:
            e = np.exp(beta * (Lp - mm))
            Z = e.sum()
            lse = mm + np.log(Z) / beta
            val = -np.log(num) + 2.0 * np.log(s) + lse
            w = e / Z
            gL = -dq / num + w
        gh = _backprop(gL, hh)
        gh += 2.0 / s
        g = gh[lo:hi][mask] * s2[mask]
        return val, g

    try:
        res = minimize(fun, x0[mask], method='L-BFGS-B', jac=True,
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3})
        out = h.copy()
        s2 = np.zeros(m)
        s2[mask] = np.exp(np.clip(res.x, -50, 50))
        out[lo:hi] = s2
        if np.all(np.isfinite(out)) and out.sum() > 0:
            return out
    except Exception:
        pass
    return h


def _zero_smallest(h, q):
    h = np.asarray(h, dtype=float).copy()
    n = h.size
    k = int(q * n)
    if k <= 0 or k >= n:
        return h
    idx = np.argpartition(h, k - 1)[:k]
    h[idx] = 0.0
    s = h.sum()
    if s <= 0:
        return h
    return h


def _revive_zeros(h, factor=1e-3):
    h = np.asarray(h, dtype=float).copy()
    pos = h > 0
    if not np.any(pos):
        return h
    posmean = h[pos].mean()
    zeros = ~pos
    if np.any(zeros):
        h[zeros] = factor * posmean
    return h


def _polish_pipeline(h, deadline, time_left, it_log=1200, it_sm=250, it_pol=300):
    best = h
    bestR = _R_of(h)
    if time_left():
        c = _lbfgs_log(best, it_log, deadline)
        if _R_of(c) > bestR:
            best = c; bestR = _R_of(c)
    for beta in (100, 500, 2000):
        if not time_left():
            break
        c = _lbfgs_sm(best, beta, it_sm, deadline)
        rc = _R_of(c)
        if rc > bestR:
            best = c; bestR = rc
    for f in (0.05, 0.10, 0.20):
        if not time_left():
            break
        c = _window_polish_peak(best, f, 8, it_pol, deadline)
        rc = _R_of(c)
        if rc > bestR:
            best = c; bestR = rc
    return best


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.975

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = _R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = _R_of(best)

    base = best.copy()
    baseR = bestR

    def try_accept(cand):
        nonlocal best, bestR
        rc = _R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    # --- EXPERIMENT: adaptive resample p0186 (N=8001) to N=64000, then fine polish ---
    experiment_best = None
    experiment_bestR = -1.0

    N = 64000
    if time_left():
        h = _adaptive_resample(base, N)
        if h.sum() > 0 and np.all(np.isfinite(h)):
            # exact log-LBFGS 1500
            if time_left():
                c = _lbfgs_log(h, 1500, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            # softmax betas 200/1000/5000/20000, 300 iters each
            for beta in (200, 1000, 5000, 20000):
                if not time_left():
                    break
                c = _lbfgs_sm(h, beta, 300, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            # exact log-LBFGS 1000
            if time_left():
                c = _lbfgs_log(h, 1000, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            # F150-style fine polish: fracs 0.02/0.04/0.08 with betas None/8000/20000
            for f, beta in ((0.02, None), (0.04, 8000), (0.08, 20000)):
                if not time_left():
                    break
                c = _window_polish_peak(h, f, 8, 300, deadline, beta=beta)
                if _R_of(c) > _R_of(h):
                    h = c
            # final exact log-LBFGS 600
            if time_left():
                c = _lbfgs_log(h, 600, deadline)
                if _R_of(c) > _R_of(h):
                    h = c
            rc = _R_of(h)
            if rc > 0:
                experiment_best = h
                experiment_bestR = rc
                if rc > bestR:
                    best = h.copy()
                    bestR = rc

    # --- Keep the base's zeroing experiment as a secondary path if time allows ---
    if time_left():
        for q in (0.10, 0.20):
            if not time_left():
                break
            hz = _zero_smallest(best, q)
            if hz.sum() <= 0:
                continue
            cand = _polish_pipeline(hz, deadline, time_left,
                                    it_log=800, it_sm=200, it_pol=250)
            rc = _R_of(cand)
            if rc > bestR:
                best = cand; bestR = rc
            if time_left():
                hr = _revive_zeros(cand, factor=1e-3)
                cand2 = _polish_pipeline(hr, deadline, time_left,
                                         it_log=600, it_sm=150, it_pol=200)
                rc2 = _R_of(cand2)
                if rc2 > bestR:
                    best = cand2; bestR = rc2

    # --- Final polishing loop on best ---
    fracs = (0.05, 0.10, 0.20, 0.15)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, 400, deadline)
        try_accept(c)
        if not time_left():
            break
        f = fracs[fi % len(fracs)]
        fi += 1
        c = _window_polish_peak(best, f, 8, 250, deadline)
        try_accept(c)

    if experiment_best is not None and experiment_bestR <= baseR and experiment_bestR > 0:
        return {"best": best, "alternative": experiment_best}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _perturb_window_at(h, lo, hi, rng, sigma=0.30):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    win = h[lo:hi]
    pos = win[win > 0]
    if pos.size > 0:
        local_mean = pos.mean()
        z = win <= 0
        if np.any(z):
            win[z] = 1e-3 * local_mean
            h[lo:hi] = win
    return _rescale(h)


def _prolongate(h, M):
    h = np.asarray(h, dtype=float)
    N = h.size
    if M == N:
        return h.copy()
    cm = np.concatenate(([0.0], np.cumsum(h)))
    total = cm[-1]
    if total <= 0:
        return np.ones(M)
    edges = np.linspace(0.0, N, M + 1)
    mass_at = np.interp(edges, np.arange(N + 1), cm)
    new_h = np.diff(mass_at)
    s = new_h.sum()
    if s > 0:
        new_h *= total / s
    return np.clip(new_h, 0, None)


def _restrict(h, M):
    return _prolongate(h, M)


def _polish_chain(h, deadline, log_iters=1200, sm_betas=(400.0, 1500.0, 4000.0),
                  sm_iters=300, polish_fracs=(0.05, 0.10, 0.20),
                  polish_extra=8, polish_iters=400):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for beta in sm_betas:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=sm_iters, deadline=deadline))
    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=log_iters, deadline=deadline))
    for frac in polish_fracs:
        if time.process_time() >= deadline - 0.5:
            break
        _try(_window_polish_peak(cur, deadline, frac, polish_extra,
                                 maxiter=polish_iters, beta=None))
    return cur, cur_r


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r:
            best, best_r = cand.copy(), r
        elif r > alt_r:
            alternative, alt_r = cand.copy(), r

    # ---------------- Strategy A: prolongation --------------
    accepted_64 = None
    if time.process_time() < hard_end - 2.0:
        h64 = _prolongate(base, 64000)
        h64, r64 = _polish_chain(h64, hard_end)
        print("prolong 64000 R=%.6f (base %.6f)" % (r64, base_r))
        if r64 > base_r:
            accepted_64 = h64
            _consider(h64, r64)
        else:
            n = h64.size
            for seed in range(4):
                if time.process_time() >= hard_end - 2.0:
                    break
                rng = np.random.default_rng(7000 + seed)
                lo = int(rng.uniform(0.0, 0.35) * n)
                hi = min(n, lo + n // 2)
                hp = _perturb_window_at(h64, lo, hi, rng, sigma=0.30)
                hp, rp = _polish_chain(hp, hard_end)
                print("  perturb seed %d R=%.6f" % (seed, rp))
                _consider(hp, rp)
                if rp > base_r and (accepted_64 is None or rp > R_of(accepted_64)):
                    accepted_64 = hp

    if accepted_64 is not None and time.process_time() < hard_end - 2.0:
        h128 = _prolongate(accepted_64, 128000)
        h128, r128 = _polish_chain(h128, hard_end, polish_iters=600)
        print("prolong 128000 R=%.6f" % r128)
        if r128 > base_r:
            _consider(h128, r128)

    # ---------------- NEW: active-set window expansion ----------------
    # The peak region of f*f is what limits R.  Mask out everything outside
    # a window around the peak, re-optimise, then re-check.  This lets the
    # optimiser concentrate DOF where it matters and can escape a plateau.
    if time.process_time() < hard_end - 2.0:
        try:
            cur = best.copy()
            cur_r = best_r
            for frac in (0.35, 0.25, 0.18, 0.12):
                if time.process_time() >= hard_end - 1.0:
                    break
                n = cur.size
                lo, hi = _peak_region(cur, tol=0.995)
                span = hi - lo
                pad = max(4, int(span * frac))
                lo = max(0, lo - pad); hi = min(n - 1, hi + pad)
                # zero outside, then renormalise
                hh = cur.copy()
                mask = np.zeros(n, dtype=bool)
                mask[lo:hi + 1] = True
                hh[~mask] = 0.0
                if hh.sum() <= 0:
                    continue
                hh = _rescale(hh)
                # re-polish the window, and also the full vector once
                hh, rh = _polish_chain(hh, hard_end, log_iters=800,
                                       sm_betas=(600.0, 2000.0),
                                       sm_iters=250,
                                       polish_fracs=(0.10, 0.20),
                                       polish_extra=6, polish_iters=400)
                print("window frac=%.2f R=%.6f" % (frac, rh))
                _consider(hh, rh)
                if rh > cur_r:
                    cur, cur_r = hh, rh
        except Exception:
            pass

    print("experiment R=%.6f N=%d | base R=%.6f N=%d"
          % (best_r, best.size, base_r, base.size))

    # ---------------- Strategy B: restriction --------------
    if time.process_time() < hard_end - 3.0:
        for Nc in (16000, 8000):
            if time.process_time() >= hard_end - 2.5:
                break
            hc = _restrict(best, Nc)
            hc, rc = _polish_chain(hc, hard_end, log_iters=1500,
                                   sm_betas=(600.0, 2000.0, 6000.0),
                                   sm_iters=400,
                                   polish_fracs=(0.10, 0.20, 0.35),
                                   polish_extra=6, polish_iters=500)
            print("restrict N=%d R=%.6f" % (Nc, rc))
            _consider(hc, rc)
            if rc > base_r:
                for Nf in (Nc * 2, min(Nc * 4, 64000)):
                    if time.process_time() >= hard_end - 2.0:
                        break
                    hf = _prolongate(hc, Nf)
                    hf, rf = _polish_chain(hf, hard_end)
                    print("  coarse->fine N=%d R=%.6f" % (Nf, rf))
                    _consider(hf, rf)

    # ---------------- Fallback polish --------------
    try:
        cur = best.copy()
        cur_r = best_r
        while time.process_time() < hard_end - 1.0:
            h = cur.copy()
            for beta in (120.0, 60.0, 30.0):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _lbfgs_sm(h, beta, maxiter=250, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            if time.process_time() < hard_end - 0.5:
                c = _lbfgs_log(h, maxiter=600, deadline=hard_end)
                if R_of(c) > R_of(h):
                    h = c
            for frac, extra in ((0.30, 16), (0.15, 8), (0.07, 4)):
                if time.process_time() >= hard_end - 0.5:
                    break
                c = _window_polish_peak(h, hard_end, frac, extra,
                                        maxiter=400, beta=None)
                if R_of(c) > R_of(h):
                    h = c
            if R_of(h) > cur_r:
                cur, cur_r = h, R_of(h)
                _consider(h, cur_r)
            if time.process_time() >= hard_end - 1.0:
                break
        print("fallback R=%.6f N=%d" % (best_r, best.size))
    except Exception:
        pass

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
        return {"best": alternative, "alternative": best}
    if alternative is not None:
        return {"best": best, "alternative": alternative}
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        if beta is None:
            val, g = _fun_grad(hh)
        else:
            val, g = _fun_grad_sm(hh, beta)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=None):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _revive_zeros(h, lo, hi, radius=256, factor=1e-3):
    h = h.copy()
    win = h[lo:hi]
    zeros = np.flatnonzero(win <= 0)
    if zeros.size == 0:
        return h
    pos_idx = np.flatnonzero(win > 0)
    if pos_idx.size == 0:
        return h
    pos_vals = win[pos_idx]
    for z in zeros:
        left = np.searchsorted(pos_idx, z - radius, side='left')
        right = np.searchsorted(pos_idx, z + radius, side='right')
        if right > left:
            lm = pos_vals[left:right].mean()
        else:
            lm = pos_vals.mean()
        win[z] = factor * lm
    h[lo:hi] = win
    return h


def _perturb_window(h, lo, hi, rng, sigma=0.35):
    h = h.copy()
    n = h.size
    lo = max(0, int(lo))
    hi = min(n, int(hi))
    W = hi - lo
    if W < 8:
        return h
    nblocks = int(rng.integers(4, 9))
    widths = rng.uniform(0.02, 0.10, size=nblocks)
    widths = widths / widths.sum()
    cuts = np.cumsum(widths * W).astype(int)
    cuts = np.clip(cuts, 1, W - 1)
    cuts = np.unique(cuts)
    edges = np.concatenate(([0], cuts, [W]))
    for b in range(edges.size - 1):
        a = lo + edges[b]
        c = lo + edges[b + 1]
        if c <= a:
            continue
        fac = np.exp(rng.normal(0.0, sigma))
        h[a:c] *= fac
    h = _revive_zeros(h, lo, hi, radius=256, factor=1e-3)
    return _rescale(h)


def _polish_chain(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=1200, deadline=deadline))
    for beta in (400.0, 1500.0, 4000.0):
        if time.process_time() >= deadline - 0.5:
            break
        _try(_lbfgs_sm(cur, beta, maxiter=300, deadline=deadline))
    if time.process_time() < deadline - 0.5:
        _try(_lbfgs_log(cur, maxiter=800, deadline=deadline))
    for frac in (0.05, 0.10, 0.20):
        if time.process_time() >= deadline - 0.5:
            break
        _try(_window_polish_peak(cur, deadline, frac, 8, maxiter=400, beta=None))
    return cur, cur_r


def _mirror(h):
    return h[::-1].copy()


def _fine_polish(h, deadline):
    cur = h
    cur_r = R_of(cur)

    def _try(cand):
        nonlocal cur, cur_r
        if cand is None:
            return
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r

    for frac in (0.02, 0.04, 0.08):
        if time.process_time() >= deadline - 0.4:
            break
        for beta in (None, 8000.0, 20000.0):
            if time.process_time() >= deadline - 0.4:
                break
            _try(_window_polish_peak(cur, deadline, frac, 4,
                                     maxiter=300, beta=beta))
    if time.process_time() < deadline - 0.4:
        _try(_lbfgs_log(cur, maxiter=600, deadline=deadline))
    return cur, cur_r


def _prolong_mass(h, N2):
    """Mass-preserving cumulative-mass prolongation to N2 steps."""
    n = h.size
    if N2 <= n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N2)
    # new step boundaries in old-index space
    edges = np.linspace(0.0, float(n), N2 + 1)
    newc = np.interp(edges, np.arange(n + 1, dtype=float), c)
    h2 = np.diff(newc)
    h2 = np.clip(h2, 0.0, None)
    if h2.sum() <= 0:
        return np.ones(N2)
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5
    hard_end = deadline - 0.5

    start_arr = None
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()

    if start_arr is None:
        cur = np.ones(512)
        cur = _lbfgs_log(cur, maxiter=800, deadline=deadline)
        return cur

    base = start_arr.copy()
    base_r = R_of(base)
    best = base.copy()
    best_r = base_r
    alternative = None
    alt_r = -1.0

    def _consider(cand, r):
        nonlocal best, best_r, alternative, alt_r
        if r > best_r + 1e-12:
            best, best_r = cand.copy(), r
        elif r > alt_r + 1e-12:
            alternative, alt_r = cand.copy(), r

    # ---- Experiment: prolong to 256000 and fine-polish ----
    N2 = 256000
    hf = _prolong_mass(base, N2)
    hf = _rescale(hf)
    r0 = R_of(hf)
    print("prolonged R=%.7f (base %.7f) N=%d" % (r0, base_r, hf.size))

    # F150-style fine polish at fine grid
    if time.process_time() < hard_end - 2.0:
        hp, rp = _fine_polish(hf, hard_end)
        print("fine polish R=%.7f" % rp)
        _consider(hp, rp)
        if rp > r0:
            hf, r0 = hp, rp

    cur = hf
    cur_r = r0
    n = cur.size

    # 10 seeded block perturbations at fine grid
    seed = 0
    while time.process_time() < hard_end - 1.0 and seed < 10:
        rng = np.random.default_rng(4242 + seed * 977)
        lo = int(rng.uniform(0.15, 0.45) * n)
        hi = min(n, lo + n // 2)
        base_for_pert = cur
        if seed % 3 == 2:
            base_for_pert = _mirror(cur)
        hp = _perturb_window(base_for_pert, lo, hi, rng, sigma=0.30)
        # polish: log-LBFGS 600 + peak-window fracs 0.05/0.10/0.20
        hp = _lbfgs_log(hp, maxiter=600, deadline=hard_end)
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= hard_end - 0.5:
                break
            cand = _window_polish_peak(hp, hard_end, frac, 8,
                                       maxiter=400, beta=None)
            if R_of(cand) > R_of(hp):
                hp = cand
        rp = R_of(hp)
        print("seed %d R=%.7f (cur %.7f base %.7f)"
              % (seed, rp, cur_r, base_r))
        _consider(hp, rp)
        if rp > cur_r + 1e-12:
            cur, cur_r = hp, rp
        seed += 1

    # Final fine polish on best
    if time.process_time() < hard_end - 0.5:
        hfin, rfin = _fine_polish(cur, hard_end)
        _consider(hfin, rfin)

    print("final R=%.7f N=%d | base R=%.7f N=%d"
          % (best_r, best.size, base_r, base.size))

    if best_r < base_r:
        best = base.copy()
        best_r = base_r

    if alternative is not None and alt_r > best_r:
