def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolongate(h, N2):
    """Cumulative-mass prolongation to N2 steps, preserving zeros."""
    n = h.size
    if n == N2:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.zeros(N2)
    # new breakpoints at j/N2 of the mass
    targets = total * np.arange(N2 + 1) / N2
    # cumulative mass at old step boundaries i/n is c[i]
    old_x = np.arange(n + 1) / n
    new_x = np.arange(N2 + 1) / N2
    mass = np.interp(new_x, old_x, c)
    h2 = np.diff(mass) * N2  # density * width scaling; shape only
    h2 = np.clip(h2, 0, None)
    return h2


def _revive_all_zeros(h, win=256, scale=1e-3):
    h = h.copy()
    n = h.size
    pos = h > 0
    if not np.any(pos):
        return h
    hp = np.where(pos, h, 0.0)
    cp = np.concatenate(([0.0], np.cumsum(hp)))
    cn = np.concatenate(([0.0], np.cumsum(pos.astype(float))))
    zeros = np.flatnonzero(h <= 0)
    for i in zeros:
        lo = max(0, i - win // 2)
        hi = min(n, i + win // 2 + 1)
        s = cp[hi] - cp[lo]
        c = cn[hi] - cn[lo]
        if c > 0:
            h[i] = scale * (s / c)
        else:
            h[i] = scale * h.max() * 1e-3
    return h


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # EXPERIMENT: prolongate to N=84992 preserving zeros, revive all zeros,
    # then log-LBFGS + softmax ladder + peak polishes.
    N2 = 84992
    if best.size != N2:
        h_pro = _prolongate(best, N2)
    else:
        h_pro = best.copy()
    h_pro = _rescale(h_pro)
    r_pro = R_of(h_pro)
    print("prolongated R=%.7f (N=%d)" % (r_pro, h_pro.size))

    # revive all zeros
    h_rev = _revive_all_zeros(h_pro, win=256, scale=1e-3)
    h_rev = _rescale(h_rev)
    r_rev = R_of(h_rev)
    print("revived R=%.7f (zeros %.1f%%)" % (r_rev, 100.0 * np.mean(h_rev <= 0)))

    cur = h_rev if r_rev > r_pro else h_pro
    if r_rev > bestR + 1e-12:
        best, bestR = h_rev, r_rev

    # Step 2: log-space L-BFGS ~1000 iters
    if time.process_time() < deadline - 8.0:
        h = _lbfgs_log(cur, 1000, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
            cur = h
        else:
            cur = h if r > bestR - 0.003 else cur

    # Step 3: softmax ladder
    for beta in (400, 1500, 5000, 20000):
        if time.process_time() >= deadline - 5.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.02, 0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # Step 4: final sharp full log-L-BFGS
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)

    # Step 5: alternate full sharp polish and narrow peak windows with remaining time
    while time.process_time() < deadline - 1.5:
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("alt sharp R=%.7f" % bestR)
        else:
            break
        for frac in (0.02, 0.05):
            if time.process_time() >= deadline - 1.0:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak frac=%.2f R=%.7f" % (frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

