def _revive_left_zeros(h, frac=0.40, win=256, scale=1e-3):
    h = h.copy()
    n = h.size
    cut = int(frac * n)
    pos = h > 0
    if not np.any(pos):
        return h
    hp = np.where(pos, h, 0.0)
    cp = np.concatenate(([0.0], np.cumsum(hp)))
    cn = np.concatenate(([0.0], np.cumsum(pos.astype(float))))
    zeros = np.flatnonzero(h[:cut] <= 0)
    for i in zeros:
        lo = max(0, i - win // 2)
        hi = min(n, i + win // 2 + 1)
        s = cp[hi] - cp[lo]
        c = cn[hi] - cn[lo]
        if c > 0:
            h[i] = scale * (s / c)
        else:
            h[i] = scale * h.max() * 1e-3
    return h


def _prolongate(h, N):
    """Resample step function h onto N steps preserving mass (piecewise-const interp)."""
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def _coarsen(h, N):
    """Average-block-reduce h to N steps (preserving mass)."""
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    vals = np.interp(xs, c, np.concatenate(([0.0], h)))
    widths = np.diff(xs)
    out = np.zeros(N)
    for i in range(N):
        out[i] = (np.interp(xs[i + 1], c, np.concatenate(([0.0], np.cumsum(np.ones(M + 1))))) -
                  np.interp(xs[i], c, np.concatenate(([0.0], np.cumsum(np.ones(M + 1))))))
    # simpler: by mass only
    mass = np.diff(np.interp(xs, c, c))
    return np.maximum(mass * (N / total), 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
