    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # NEW IDEA: try higher-resolution refinements. The original is stuck at N.
    # Upsample the current best to larger N, polish there, keep if better.
    # Also try a coarse-then-fine continuation.

    cur = best.copy()

    # Phase A: quick beta polish at current N to lock-in a good point.
    for beta in (1e4, 1e5):
