        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR, cur = h, r, h
            print("beta=%.0e R=%.7f" % (beta, r))
        else:
            cur = h

    # Phase B: resolution sweep. Try upsampling to 1.5x and 2x of current N.
    for mult in (1.5, 2.0):
        if time.process_time() >= deadline - 12.0:
            break
        newN = int(min(900000, best.size * mult))
        if newN <= best.size + 100:
            continue
        cand = _prolongate(best, newN)
        cand = _rescale(cand)
        r0 = R_of(cand)
        print("upsample x%.1f N=%d R0=%.7f" % (mult, newN, r0))
        # Polish at new resolution
        h = _lbfgs_log(cand, 300, deadline, beta=5e4)
        r = R_of(h)
        print("  up-polish R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR, cur = h, r, h
        else:
            # keep orig; try polishing new cand's peak region anyway
            hp = _window_polish_peak(cand, deadline, 0.15, 64, maxiter=250, beta=5e4)
            rp = R_of(hp)
