def _prolongate(h_small, N_big):
    n = h_small.size
    if n == N_big:
        return h_small.copy()
    S = np.concatenate(([0.0], np.cumsum(h_small)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    h = np.clip(np.diff(Sb), 0.0, None)
    if h.sum() <= 0:
        return np.ones(N_big)
    return h


def _smoothstep(h, N_big, rounds=2):
    # resample via smooth interpolation to reduce grid artifacts
    n = h.size
    S = np.concatenate(([0.0], np.cumsum(h)))
    xs = np.linspace(0.0, 1.0, n + 1)
    xb = np.linspace(0.0, 1.0, N_big + 1)
    Sb = np.interp(xb, xs, S)
    Sb = np.maximum.accumulate(Sb)
    ho = np.clip(np.diff(Sb), 0.0, None)
    for _ in range(rounds):
        k = np.array([1.0, 2.0, 3.0, 2.0, 1.0]); k /= k.sum()
        ho = np.convolve(ho, k, mode='same')
        ho = np.clip(ho, 0, None)
    if ho.sum() <= 0:
        return _prolongate(h, N_big)
    return ho


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.92

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            start_best = _rescale(base)
            start_bestR = R_of(start_best)
        else:
            start_best, start_bestR = None, 0.0
    else:
        start_best, start_bestR = None, 0.0

    if start_best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        start_best = _rescale(h)
        start_bestR = R_of(start_best)

    print("base R=%.7f (N=%d)" % (start_bestR, start_best.size))

    best = start_best.copy()
    bestR = start_bestR
    alt = None
    altR = -1.0

    def _try(h, tag):
        nonlocal best, bestR, alt, altR
        h = _rescale(h)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("%s R=%.7f" % (tag, r))
        elif r > altR:
            alt, altR = h.copy(), r
        return r

    N0 = start_best.size
    N1 = min(1000000, 2 * N0)

    # Try both plain prolongation and smoothed resample; keep the better seed.
    cand_a = _rescale(_prolongate(start_best, N1))
    cand_b = _rescale(_smoothstep(start_best, N1, rounds=1))
    ra, rb = R_of(cand_a), R_of(cand_b)
    cur = cand_a if ra >= rb else cand_b
    print("prolongate N=%d R=%.7f (smooth=%.7f)" % (N1, max(ra, rb), rb))
    if R_of(cur) > bestR + 1e-12:
        best, bestR = cur.copy(), R_of(cur)

    # Stage 1: exact log-L-BFGS
    if time.process_time() < deadline - 20.0:
        h = _lbfgs_log(cur, 800, deadline)
        if _try(h, "log800") > R_of(cur):
            cur = h

    # Stage 2: softmax betas (tightening) - key for pushing peak flat
    for beta in (20.0, 60.0, 200.0, 600.0, 2000.0):
        if time.process_time() >= deadline - 14.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        _try(h, "beta%.0f" % beta)
        if R_of(h) > R_of(cur) - 0.001:
            cur = h

    # Stage 3: narrow peak-window fine polish (multi-scale)
    for frac, extra in ((0.005, 16), (0.01, 24), (0.02, 32), (0.04, 48), (0.08, 64)):
        if time.process_time() >= deadline - 8.0:
            break
        h = _window_polish_peak(cur, deadline, frac, extra, maxiter=200)
        _try(h, "win%.3f" % frac)
        if R_of(h) > R_of(cur) - 0.001:
            cur = h

    # Stage 4: exact log-L-BFGS again
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 500, deadline)
        _try(h, "log500")
        if R_of(h) > R_of(cur) - 0.001:
            cur = h

    # Stage 5: peak-window polish with beta smoothness at larger windows
    for frac, extra, beta in ((0.10, 64, 200.0), (0.20, 96, 200.0), (0.30, 128, 0.0)):
        if time.process_time() >= deadline - 3.0:
            break
        h = _window_polish_peak(best, deadline, frac, extra, maxiter=250, beta=beta)
        _try(h, "broad%.2f" % frac)

    # Stage 6: continue polishing best
    while time.process_time() < deadline - 1.0:
        h = _lbfgs_log(best, 400, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("polish R=%.7f" % bestR)
        else:
            break

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    out = {"best": start_best}
    if alt is not None and altR > start_bestR - 1e-6:
        out["alternative"] = alt
    return out

