def _local_mean(h, win=256):
    pos = h > 0
    hp = np.where(pos, h, 0.0)
    cp = np.concatenate(([0.0], np.cumsum(hp)))
    cn = np.concatenate(([0.0], np.cumsum(pos.astype(float))))
    n = h.size
    out = np.zeros(n)
    half = win // 2
    for i in range(n):
        lo = max(0, i - half)
        hi = min(n, i + half + 1)
        c = cn[hi] - cn[lo]
        if c > 0:
            out[i] = (cp[hi] - cp[lo]) / c
        else:
            out[i] = h.max() * 1e-3
    return out


def _gradient_revive(h, frac, scale):
    """Revive the most-negative-gradient exact zeros to scale*local_mean."""
    n = h.size
    zeros = np.flatnonzero(h <= 0)
    if zeros.size == 0:
        return h, 0
    _, g = _fun_grad(h)
    gz = g[zeros]
    order = np.argsort(gz)  # ascending: most negative first
    k = max(1, int(frac * n))
    k = min(k, zeros.size)
    chosen = zeros[order[:k]]
    lm = _local_mean(h, win=256)
    h2 = h.copy()
    h2[chosen] = scale * lm[chosen]
    return h2, k


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    cur = best.copy()
    scale = 1e-3

    # Gradient-gated zero revival, up to 3 rounds.
    for rnd in range(3):
        if time.process_time() >= deadline - 8.0:
            break
        h_rev, k = _gradient_revive(cur, frac=0.07, scale=scale)
        h_rev = _rescale(h_rev)
        r_rev = R_of(h_rev)
        print("round %d: revived %d zeros (scale %.1e) R=%.7f" %
              (rnd, k, scale, r_rev))
        if time.process_time() < deadline - 4.0:
            h_pol = _lbfgs_log(h_rev, 500, deadline)
            r_pol = R_of(h_pol)
            print("  polish R=%.7f" % r_pol)
        else:
            h_pol, r_pol = h_rev, r_rev
        if r_pol > bestR + 1e-12:
            best, bestR = h_pol, r_pol
            cur = h_pol
            print("  accepted R=%.7f (zeros %.1f%%)" %
                  (bestR, 100.0 * np.mean(best <= 0)))
        else:
            cur = h_pol if r_pol > bestR - 0.003 else cur
        scale *= 1e-3

    # Beta-softmax ladder interleaved with peak polishes.
    for beta in (1e3, 1e4, 5e4, 2e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # Spend remaining budget alternating full polish + peak polishes.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

