    m = (n - 1) * factor + 1
    if m > 1000000:
        return None
    x_old = np.arange(n, dtype=float)
    x_new = np.arange(m, dtype=float) / factor
    h_new = np.interp(x_new, x_old, h)
    return _rescale(h_new)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(h)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    cur = best.copy()

    # Stage A: sharp log-space full L-BFGS.
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 800, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur

    # Stage B: beta sweep + peak polishes.
    for beta in (1e3, 1e4, 5e4, 2e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
        cur = h if r > bestR - 0.003 else cur
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 32,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            cur = hp if rp > bestR - 0.003 else cur

    # NEW Stage B2: try grid refinement — subdivide and re-optimize.
    # Inserting finer steps in the peak region may recover extra resolution.
    if time.process_time() < deadline - 8.0:
        for factor in (2,):
            if time.process_time() >= deadline - 6.0:
                break
            hr = _refine_grid(best, factor, deadline)
            if hr is None:
                continue
            # local polish on peak region of refined grid
            hp = _window_polish_peak(hr, deadline, 0.10, 64,
                                     maxiter=300)
            rp = R_of(hp)
            print("refine x%d R=%.7f" % (factor, rp))
            if rp > bestR + 1e-12:
                best, bestR = hp, rp

    # Stage C: final sharp.
    if time.process_time() < deadline - 2.0:
        h = _lbfgs_log(best, 500, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)

    # Stage D: alternate full sharp + peak polish until near deadline.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _coarsen(h, factor):
    n = h.size
    m = n // factor
    if m < 1:
        return h.copy()
    hc = h[:m * factor].reshape(m, factor).sum(axis=1)
    return hc


def _prolongate(hc, n_target):
    m = hc.size
    cum = np.concatenate(([0.0], np.cumsum(hc)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(n_target)
    edges = np.linspace(0.0, total, n_target + 1)
    vals = np.interp(edges, cum, np.arange(m + 1, dtype=float))
    vals = np.clip(vals, 0.0, m)
    idx = np.floor(vals).astype(int)
    idx = np.clip(idx, 0, m - 1)
    frac = vals - idx
    hf = hc[idx] * (1.0 - frac) + hc[np.clip(idx + 1, 0, m - 1)] * frac
    return hf


def _coarse_ladder(hc, deadline, betas, fracs):
    best = hc.copy()
    bestR = R_of(best)
    cur = best.copy()
    h = _lbfgs_log(cur, 1000, deadline)
    r = R_of(h)
    if r > bestR:
        best, bestR = h, r
    cur = h if r > bestR - 0.003 else cur
    for _pass in range(6):
        if time.process_time() >= deadline - 2.0:
            break
        improved = False
        for beta in betas:
            if time.process_time() >= deadline - 1.5:
                break
            h = _lbfgs_log(cur, 250, deadline, beta=beta)
            r = R_of(h)
            if r > bestR + 1e-12:
                best, bestR = h, r
                improved = True
            cur = h if r > bestR - 0.003 else cur
            for frac in fracs:
                if time.process_time() >= deadline - 1.0:
                    break
                hp = _window_polish_peak(cur, deadline, frac, 32,
                                         maxiter=200, beta=beta)
                rp = R_of(hp)
                if rp > bestR + 1e-12:
                    best, bestR = hp, rp
                    improved = True
                cur = hp if rp > bestR - 0.003 else cur
        if not improved:
            break
    return best, bestR


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    N0 = best.size
    print("base R=%.7f (N=%d)" % (bestR, N0))

    # Stage 1-3: coarse reshaping.
    factor = 4
    Nc = N0 // factor
    coarse_ok = False
    if Nc >= 16 and time.process_time() < deadline - 20.0:
        hc = _coarsen(best, factor)
        hc = _rescale(hc)
        rc0 = R_of(hc)
        print("coarse R=%.7f (N=%d)" % (rc0, hc.size))
        # Reserve ~40% of remaining time for coarse stage.
        coarse_deadline = time.process_time() + (deadline - time.process_time()) * 0.45
        hc_best, rc_best = _coarse_ladder(hc, coarse_deadline,
                                          (1e3, 1e4, 1e5),
                                          (0.05, 0.10, 0.20))
        print("coarse best R=%.7f" % rc_best)
        # Prolongate back to N0.
        if time.process_time() < deadline - 10.0:
            hp = _prolongate(hc_best, N0)
            hp = _rescale(hp)
            rp = R_of(hp)
            print("prolong R=%.7f" % rp)
            # Polish at fine grid.
            h = _lbfgs_log(hp, 800, deadline)
            r = R_of(h)
            print("prolong log R=%.7f" % r)
            if r > rp:
                hp, rp = h, r
            cur = hp
            for beta in (1e4, 1e5):
                if time.process_time() >= deadline - 6.0:
                    break
                h = _lbfgs_log(cur, 250, deadline, beta=beta)
                r = R_of(h)
                if r > rp:
                    hp, rp = h, r
                cur = h if r > rp - 0.003 else cur
                for frac in (0.05, 0.10, 0.20):
                    if time.process_time() >= deadline - 4.0:
                        break
                    hw = _window_polish_peak(cur, deadline, frac, 32,
                                             maxiter=200, beta=beta)
                    rw = R_of(hw)
                    if rw > rp:
                        hp, rp = hw, rw
                    cur = hw if rw > rp - 0.003 else cur
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                coarse_ok = True
                print("accepted coarse R=%.7f" % bestR)

    # Stage 4: if accepted and time remains, prolongate to 2*N0.
    if coarse_ok and time.process_time() < deadline - 15.0:
        N1 = N0 * 2
        if N1 <= 1000000:
            hp2 = _prolongate(best, N1)
            hp2 = _rescale(hp2)
            r2 = R_of(hp2)
            print("prolong2 R=%.7f (N=%d)" % (r2, N1))
            h = _lbfgs_log(hp2, 400, deadline)
            r = R_of(h)
            if r > r2:
                hp2, r2 = h, r
            for frac in (0.02, 0.05):
                if time.process_time() >= deadline - 4.0:
                    break
                hw = _window_polish_peak(hp2, deadline, frac, 32, maxiter=200)
                rw = R_of(hw)
                if rw > r2:
                    hp2, r2 = hw, rw
            if r2 > bestR + 1e-12:
                best, bestR = hp2, r2
                print("accepted prolong2 R=%.7f" % bestR)

    # Stage D: alternate full sharp + peak polish until near deadline.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("  alt full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-13:
                best, bestR = hp, rp
                print("  alt peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

