    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _prolong(h, N):
    """Cumulative-mass prolongation to N steps, preserving exact zeros."""
    n = h.size
    if N == n:
        return h.copy()
    h = np.clip(h, 0, None)
    cum = np.concatenate(([0.0], np.cumsum(h)))
    total = cum[-1]
    if total <= 0:
        return np.zeros(N)
    # new cell boundaries in old-index coordinates
    edges = np.linspace(0.0, n, N + 1)
    mass = np.interp(edges, np.arange(n + 1), cum)
    out = np.diff(mass)
    # density correction: each new cell is (n/N) wide in old units
    out *= (N / n)
    # preserve exact zeros: if an old cell is zero, new cells inside it are zero
    # (interp of a flat cumsum gives exactly zero increments there already)
    out = np.clip(out, 0, None)
    return out


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # Prolong to 4x grid
    N4 = best.size * 4
    cur = _rescale(_prolong(best, N4))
    r = R_of(cur)
    print("prolonged N=%d R=%.7f" % (cur.size, r))
    if r > bestR + 1e-12:
        best, bestR = cur.copy(), r
    # keep cur as the working point regardless (it's the 4x representation)

    # Stage A: sharp log full polish
    if time.process_time() < deadline - 5.0:
        h = _lbfgs_log(cur, 600, deadline)
        r = R_of(h)
        print("log-lbfgs R=%.7f" % r)
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        if r > bestR - 0.003:
            cur = h

    # Stage B: beta ladder with peak polishes
    for beta in (1e3, 1e4, 1e5):
        if time.process_time() >= deadline - 4.0:
            break
        h = _lbfgs_log(cur, 250, deadline, beta=beta)
        r = R_of(h)
        print("beta=%.0e R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h.copy(), r
        if r > bestR - 0.003:
            cur = h
        for frac in (0.01, 0.02, 0.05):
            if time.process_time() >= deadline - 3.0:
                break
            hp = _window_polish_peak(cur, deadline, frac, 48,
                                     maxiter=200, beta=beta)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp.copy(), rp
                print("  peak frac=%.2f R=%.7f" % (frac, rp))
            if rp > bestR - 0.003:
                cur = hp

    # Stage C: loop sharp full + 0.02 window polish
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h.copy(), r
            print("  alt full #%d R=%.7f" % (it, bestR))
        if time.process_time() >= deadline - 1.5:
            break
        hp = _window_polish_peak(best, deadline, 0.02, 48, maxiter=200)
        rp = R_of(hp)
        if rp > bestR + 1e-13:
            best, bestR = hp.copy(), rp
            print("  alt peak #%d R=%.7f" % (it, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    def cb(xk):
        if time.process_time() > deadline - 0.2:
            raise TimeoutError

    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _prolong(h, N):
    """Cumulative-mass prolongation to N steps, preserving exact zeros."""
    h = np.asarray(h, dtype=float)
    M = h.size
    if M == N:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    total = c[-1]
    if total <= 0:
        return np.ones(N)
    xs = np.linspace(0.0, total, N + 1)
    out = np.interp(xs, c, np.arange(M + 1, dtype=float))
    idx = np.clip(np.floor(out).astype(int), 0, M - 1)
    return np.maximum(h[idx], 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def time_left():
        return time.process_time() < deadline

    best = None
    bestR = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            best = s.copy()
            bestR = R_of(best)

    if best is None:
        best = np.ones(64)
        bestR = R_of(best)

    h = best.copy()

    def try_accept(cand):
        nonlocal best, bestR
        rc = R_of(cand)
        if rc > bestR:
            bestR = rc
            best = cand.copy()
            return True
        return False

    # refine at current resolution first, then progressively increase N
    start_N = h.size
    levels = sorted(set([start_N, max(start_N * 2, 2000), 16000, 48000, 96000]))
    levels = [N for N in levels if N <= 1000000]

    for li, N in enumerate(levels):
        if not time_left():
            break
        h = _prolong(h, N)
        try_accept(h)
        it_log = 2000 if li == 0 else 900
        it_sm = 300
        it_pol = 400

        if time_left():
            c = _lbfgs_log(h, it_log, deadline)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)

        for beta in (50, 200, 800, 3000):
            if not time_left():
                break
            c = _lbfgs_log(h, it_sm, deadline, beta=beta)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)

        if time_left():
            c = _lbfgs_log(h, it_log, deadline)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)

        # peak-region polish, growing window
        for frac in (0.05, 0.10, 0.20, 0.35, 0.50):
            if not time_left():
                break
            lo, hi = _peak_region(h, tol=0.999)
            span = max(1, hi - lo)
            pad = max(8, int(span * frac))
            lo2 = max(0, lo - pad)
            hi2 = min(h.size - 1, hi + pad)
            free = np.arange(lo2, hi2 + 1)
            c = _lbfgs_block(h, free, it_pol, deadline)
            if R_of(c) > R_of(h):
                h = c
            try_accept(h)

    # final polishing on best
    fracs = (0.10, 0.20, 0.35, 0.05, 0.50)
    fi = 0
    while time_left():
        c = _lbfgs_log(best, 400, deadline)
        try_accept(c)
        if not time_left():
            break
        frac = fracs[fi % len(fracs)]
        fi += 1
        lo, hi = _peak_region(best, tol=0.999)
        span = max(1, hi - lo)
        pad = max(8, int(span * frac))
        lo2 = max(0, lo - pad)
        hi2 = min(best.size - 1, hi + pad)
        free = np.arange(lo2, hi2 + 1)
        c = _lbfgs_block(best, free, 300, deadline)
        try_accept(c)
        if not time_left():
            break
        beta = (100, 500, 2000, 8000)[fi % 4]
        c = _lbfgs_log(best, 300, deadline, beta=beta)
        try_accept(c)

    return best

