            if rp > curR - 1e-6:
                cur, curR = hp, rp

    # ---- Step 2: aggressive tiny-perturbation climb.
    # Take the current best, add a very small smooth multiplicative
    # perturbation, polish, and keep if improved. This explores the
    # immediate neighbourhood which full polishing alone cannot escape.
    sigmas = (0.002, 0.004, 0.008, 0.015, 0.03, 0.05)
    for si, sigma in enumerate(sigmas):
        if time.process_time() >= deadline - 5.0:
            break
        rng = np.random.default_rng(7000 + si)
        for wsel in (width, max(2, width // 3), max(2, width // 8)):
            if time.process_time() >= deadline - 4.0:
                break
            noise = _smooth_noise(rng, N, wsel)
            cand = _rescale(best * np.exp(sigma * noise))
            h = _lbfgs_log(cand, 300, deadline)
            r = R_of(h)
            if r > bestR + 1e-12:
                best, bestR = h, r
                print("pert sig=%.3f w=%d R=%.7f" % (sigma, wsel, r))
                cur, curR = h, r
            # peak polish on the perturb result regardless
            hp = _window_polish_peak(h, deadline, 0.10, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  pert-peak R=%.7f" % rp)
                cur, curR = hp, rp

    # ---- Step 3: final alternating polish loop until deadline.
    it = 0
    while time.process_time() < deadline - 2.0:
        it += 1
        h = _lbfgs_log(best, 300, deadline)
        r = R_of(h)
        if r > bestR + 1e-12:
            best, bestR = h, r
            print("  final full #%d R=%.7f" % (it, bestR))
        for frac in (0.05, 0.10, 0.20, 0.35):
            if time.process_time() >= deadline - 1.5:
                break
            hp = _window_polish_peak(best, deadline, frac, 32, maxiter=200)
            rp = R_of(hp)
            if rp > bestR + 1e-12:
                best, bestR = hp, rp
                print("  final peak #%d frac=%.2f R=%.7f" % (it, frac, rp))

    print("final R=%.7f (N=%d, zeros %.1f%%)" %
          (bestR, best.size, 100.0 * np.mean(best <= 0)))

    if bestR > start_bestR + 1e-12:
        return best
    return {"best": start_best,
            "alternative": best if bestR > start_bestR - 1e-6 else None}

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 1500:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 1500:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_beta(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    mx = Lf.max()
    if mx <= 0:
        return _fun_grad(h)
    e = np.exp(beta * (Lf - mx))
    Z = e.sum()
    if Z <= 0:
        return _fun_grad(h)
    w = e / Z
    sm = mx + np.log(Z) / beta
    gLf = -dq / num + w / sm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(sm)
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = fg(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline, beta=0.0):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()
    if beta > 0:
        fg = (lambda hh: _fun_grad_beta(hh, beta))
    else:
        fg = _fun_grad

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = fg(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except (TimeoutError, Exception):
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _window_polish_peak(h, deadline, frac, extra, maxiter=400, beta=0.0):
    n = h.size
    lo, hi = _peak_region(h)
    span = hi - lo
    pad = max(extra, int(span * frac))
    lo = max(0, lo - pad)
    hi = min(n - 1, hi + pad)
    free = np.arange(lo, hi + 1)
    return _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline, beta=beta)


def _up_resample(h, N_big):
    n = h.size
    if n == N_big:
        return h.copy()
    x = np.linspace(0.0, 1.0, n)
    xb = np.linspace(0.0, 1.0, N_big)
    hb = np.interp(xb, x, h)
    return np.clip(hb, 0.0, None)


def _peak_flatten(h, deadline, target_frac=0.5, maxiter=200, beta=3000.0):
    """Drive the whole near-maximal plateau toward equality by using an
    extremely strong softmax so the gradient concentrates on raising
    the *lower* near-peak knots, flattening the top of the autoconvolution."""
    return _window_polish_peak(h, deadline, 0.4, 32, maxiter=maxiter, beta=beta)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    if start is not None:
        base = np.clip(np.asarray(start, dtype=float).copy(), 0, None)
        if base.size > 0 and base.sum() > 0:
            best = _rescale(base)
            bestR = R_of(best)
        else:
            best, bestR = None, 0.0
    else:
        best, bestR = None, 0.0

    if best is None:
        N = 8192
        i = np.arange(N, dtype=float)
        h = 2.0 * np.sqrt(N) * (np.sqrt(i + 1.0) - np.sqrt(i))
        best = _rescale(h)
        bestR = R_of(best)

    start_best = best.copy()
    start_bestR = bestR
    print("base R=%.7f (N=%d)" % (bestR, best.size))

    # KEY CHANGE: instead of trying to grow the grid (which was already
    # plateauing), spend the budget flattening the top of f*f on the
    # existing grid with progressively sharper softmax surrogates.
    # A perfectly flat top is the exact regime where R is maximised
    # (Hoelder equality), so pushing the near-peak knots together
    # directly attacks the remaining gap.  We also do periodic sharp
    # (no-softmax) polish to lock in the gain.

    cur = best.copy()
    for beta in (400.0, 800.0, 1500.0, 3000.0, 6000.0):
        if time.process_time() >= deadline - 6.0:
            break
        h = _peak_flatten(cur, deadline, maxiter=300, beta=beta)
        r = R_of(h)
        print("flat beta=%.0f R=%.7f" % (beta, r))
        if r > bestR + 1e-12:
            best, bestR = h, r
            cur = h
        elif r > bestR - 0.001:
            cur = h

    # Sharp polish on the full support to consolidate.
    if time.process_time() < deadline - 4.0:
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("sharp R=%.7f" % bestR)

    # Now try one grid refinement, since we've pushed the plateau as far
    # as the current resolution allows; extra resolution may resolve
    # small residual structure in the peak.
    if time.process_time() < deadline - 15.0:
        N0 = best.size
        Nt = int(min(1000000, max(N0 + 512, int(N0 * 1.4))))
        hu = _up_resample(best, Nt)
        hu = _rescale(hu)
        hu = _peak_flatten(hu, deadline, maxiter=250, beta=1500.0)
        hu = _lbfgs_log(hu, 400, deadline)
        r = R_of(hu)
        print("lift N=%d R=%.7f" % (Nt, r))
        if r > bestR + 1e-12:
            best, bestR = hu, r
            cur = hu

    # Final sharp passes alternating with softmax flattening.
    for _ in range(4):
        if time.process_time() >= deadline - 2.0:
            break
        h = _lbfgs_log(best, 800, deadline)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final sharp R=%.7f" % bestR)
        if time.process_time() >= deadline - 4.0:
            break
        h = _peak_flatten(best, deadline, maxiter=200, beta=4000.0)
        r = R_of(h)
        if r > bestR + 1e-13:
            best, bestR = h, r
            print("final flat R=%.7f" % bestR)

    print("final R=%.7f (N=%d)" % (bestR, best.size))

    if bestR > start_bestR + 1e-12:
        return best
    alt = best if bestR > start_bestR - 1e-6 else None
    return {"best": start_best, "alternative": alt}

