    while N <= 65536:
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            h, cur_r = cand, r
        cand, r = _homotopy(h, betas, 200, deadline)
        if r > cur_r:
            h, cur_r = cand, r
        print("  level N=%d R=%.6f" % (N, cur_r))
        if N >= 65536:
            break
        N = min(N * 2, 65536)
        h = _rescale(_prolong(h, N))
        cur_r = R_of(h)

    fresh = h.copy()
    fresh_r = cur_r

    # Refine fresh at N=65536.
    if fresh.size >= 65536:
        fresh, fresh_r = _refine_from(fresh, fresh_r, deadline)
        print("  fresh refined R=%.6f" % fresh_r)

    # Now refine start too, with the remaining budget, alternating.
    best = fresh.copy()
    best_r = fresh_r
    if start_arr is not None:
        if start_r > best_r:
            best, best_r = start_arr.copy(), start_r
        # If start is same size, run alternating refinement on it too.
        sref = start_arr.copy()
        sref_r = start_r
        while time.process_time() < deadline - 1.5:
            sref, sref_r = _refine_from(sref, sref_r, deadline)
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
