    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = s.copy()
            start_r = R_of(_rescale(s.copy()))

    # Fresh ladder from a smooth bump.
    N0 = 64
    x = np.linspace(0, 1, N0)
    h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
    h = _rescale(h)
    cur_r = R_of(h)
    print("ladder start R=%.6f N=%d" % (cur_r, h.size))

    betas = (8, 32, 128, 512, 2048)
    N = N0
    while N <= 65536:
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            h, cur_r = cand, r
        cand, r = _homotopy(h, betas, 200, deadline)
        if r > cur_r:
            h, cur_r = cand, r
        print("  level N=%d R=%.6f" % (N, cur_r))
        if N >= 65536:
            break
        N = min(N * 2, 65536)
        h = _rescale(_prolong(h, N))
        cur_r = R_of(h)

    fresh = h.copy()
    fresh_r = cur_r

    if fresh.size >= 65536:
        fresh, fresh_r = _polish(fresh, deadline, fresh_r,
                                 fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400)
        print("  after peak polish R=%.6f" % fresh_r)
        while time.process_time() < deadline - 1.5:
            cand = _lbfgs_log(fresh, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > fresh_r:
                fresh, fresh_r = cand, r
            cand, r = _polish(fresh, deadline, fresh_r,
                              fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400)
            if r > fresh_r:
                fresh, fresh_r = cand, r
            print("  alt R=%.6f" % fresh_r)

    print("fresh R=%.6f (start %.6f)" % (fresh_r, start_r))

    # NEW: refine the start construction too, at higher resolution, and
    # continue polishing whichever is better with the remaining time.
    best = fresh
    best_r = fresh_r

    if start_arr is not None:
        # Prolong the start to 65536 and polish it (a genuinely different line).
        if start_arr.size < 65536:
            s_hi = _rescale(_prolong(_rescale(start_arr), 65536))
        else:
            s_hi = _rescale(start_arr)
        s_r = R_of(s_hi)
        if time.process_time() < deadline - 3.0:
            s_hi, s_r = _polish(s_hi, deadline, s_r,
                                fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400)
        if time.process_time() < deadline - 2.0:
            cand = _lbfgs_log(s_hi, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > s_r:
                s_hi, s_r = cand, r
        print("  start-refined R=%.6f (was %.6f)" % (s_r, start_r))
        if s_r > best_r:
            best, best_r = s_hi, s_r
        else:
            s_hi = s_hi  # keep as alternative candidate

        # Final combined polish of best with remaining time.
        while time.process_time() < deadline - 1.5:
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            cand, r = _polish(best, deadline, best_r,
                              fracs=(0.20, 0.10, 0.05, 0.02), maxiter=400)
            if r > best_r:
                best, best_r = cand, r
            print("  final R=%.6f" % best_r)

        print("best R=%.6f" % best_r)
        if start_r > best_r:
            return {"best": _rescale(start_arr), "alternative": best}
        return {"best": best, "alternative": _rescale(start_arr)}

    return fresh

