def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_from(h, rcur, deadline):
    betas = (64, 256, 1024, 4096)
    while time.process_time() < deadline - 1.5:
        improved = False
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r; improved = True
        cand, r = _polish(h, deadline, rcur, maxiter=400)
        if r > rcur:
            h, rcur = cand, r; improved = True
        if time.process_time() < deadline - 4.0:
            cand, r = _homotopy(h, betas, 150, deadline)
            if r > rcur:
                h, rcur = cand, r; improved = True
        if not improved:
            break
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.5

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0
    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
        print("start R=%.6f N=%d" % (start_r, start_arr.size))

    # ---- New idea: 2x finer grid built from start, then refine ----
    alt = None
    alt_r = -1.0
    if start_arr is not None and best is not None and start_arr.size <= 500000:
        try:
            finer = _rescale(_prolong(best, best.size * 2))
            finer_r = R_of(finer)
            finer, finer_r = _refine_from(finer, finer_r, deadline)
            alt, alt_r = finer, finer_r
            print("finer (2x) R=%.6f N=%d" % (alt_r, alt.size))
        except Exception:
            pass

    # Try refining the start directly at its own size, maybe with shift align + polish
    if start_arr is not None and time.process_time() < deadline - 3.0:
        try:
            h = start_arr.copy()
            r = start_r
            # shift-align to itself is noop, but polish may improve
            h2, r2 = _polish(h, deadline, r)
            if r2 > best_r:
                best, best_r = h2, r2
        except Exception:
            pass

    # Compare candidates and keep improving the best
    if alt is not None and alt_r > best_r:
        best, best_r = alt, alt_r

    # Final refinement loop on best
    while time.process_time() < deadline - 1.5:
        try:
            cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
            r = R_of(cand)
            if r > best_r:
                best, best_r = cand, r
            cand, r = _polish(best, deadline, best_r, maxiter=400)
            if r > best_r:
                best, best_r = cand, r
            # Try a softmax continuation at the current size
            c2, r2 = _homotopy(best, (128, 512, 2048), 150, deadline)
            if r2 > best_r:
                best, best_r = c2, r2
            else:
                break
        except Exception:
            break

    print("best R=%.6f (start %.6f, alt %.6f)" % (best_r, start_r, alt_r))

    if start_arr is not None and alt is not None:
        if best_r <= start_r and alt_r <= start_r:
            return {"best": start_arr, "alternative": alt}
        if best is not None and best_r > start_r:
            return {"best": best, "alternative": alt}
    if best is not None and best_r > start_r:
        return best
    if start_arr is not None:
        return start_arr
    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(h):
    if h.size > 4000:
        return fftconvolve(h, h)
    return np.convolve(h, h)


def _knots(h):
    return np.concatenate(([0.0], _conv(h), [0.0]))


def R_of(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = _knots(h)
    a = L[:-1]; b = L[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    den = s * s * L.max()
    if den <= 0:
        return 0.0
    return num / den


def _num_and_dq(h):
    Lf = _knots(h)
    a = Lf[:-1]; b = Lf[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    dq = np.zeros_like(Lf)
    dq[:-1] += (2 * a + b)
    dq[1:] += (a + 2 * b)
    dq /= 3.0
    return num, dq, Lf


def _backprop(gLf, h):
    gL = gLf[1:-1]
    n = h.size
    if n > 4000:
        return 2.0 * fftconvolve(gL, h[::-1], mode='valid')[:n]
    return 2.0 * np.correlate(gL, h, mode='valid')[:n]


def _rescale(h):
    h = np.clip(h, 0, None)
    if h.sum() <= 0:
        return h
    mx = _knots(h).max()
    if mx <= 0:
        return h
    return h / np.sqrt(mx)


def _fun_grad(h):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    m = int(np.argmax(Lf))
    Lm = Lf[m]
    gLf = -dq / num
    gLf[m] += 1.0 / Lm
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + np.log(Lm)
    return val, grad


def _fun_grad_sm(h, beta):
    s = h.sum()
    if s <= 0:
        return 1e18, np.zeros(h.size)
    num, dq, Lf = _num_and_dq(h)
    M = Lf.max()
    if M <= 0:
        return 1e18, np.zeros(h.size)
    z = beta * (Lf - M)
    w = np.exp(z)
    S = w.sum()
    logLm = M + np.log(S) / beta
    gLf = -dq / num
    gLf += w / S
    grad = _backprop(gLf, h) + 2.0 / s
    val = -np.log(num) + 2.0 * np.log(s) + logLm
    return val, grad


def _make_cb(deadline):
    def cb(xk):
        if time.process_time() > deadline:
            raise TimeoutError
    return cb


def _lbfgs_log(h0, maxiter, deadline, active_mask=None):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    if active_mask is None:
        thresh = 1e-13 * h.max()
        active = np.flatnonzero(h > thresh)
    else:
        active = np.flatnonzero(active_mask)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad(hh)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_sm(h0, beta, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    n = h.size
    thresh = 1e-13 * h.max()
    active = np.flatnonzero(h > thresh)
    if active.size == 0:
        return h0
    u0 = np.log(np.clip(h[active], 1e-300, None))

    def f(u):
        uu = np.clip(u, -30.0, 30.0)
        hh = np.zeros(n)
        hh[active] = np.exp(uu)
        val, g = _fun_grad_sm(hh, beta)
        return val, g[active] * hh[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, u0, jac=True, method='L-BFGS-B',
                       bounds=[(-30.0, 30.0)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = np.zeros(n)
    h2[active] = np.exp(np.clip(res.x, -30.0, 30.0))
    return _rescale(h2)


def _lbfgs_block(h0, free, maxiter, deadline):
    if time.process_time() >= deadline - 0.3:
        return h0
    h = np.clip(h0, 0, None)
    if h.sum() <= 0:
        return h0
    active = np.asarray(free, dtype=int)
    if active.size == 0:
        return h0
    x0 = h[active].copy()

    def f(x):
        hh = h.copy()
        hh[active] = np.clip(x, 0.0, None)
        val, g = _fun_grad(hh)
        return val, g[active]

    cb = _make_cb(deadline - 0.2)
    try:
        res = minimize(f, x0, jac=True, method='L-BFGS-B',
                       bounds=[(0.0, None)] * active.size,
                       callback=cb,
                       options={'maxiter': maxiter, 'maxfun': 2 * maxiter,
                                'ftol': 1e-20, 'gtol': 1e-16})
    except Exception:
        return h0
    if res is None:
        return h0
    h2 = h.copy()
    h2[active] = np.clip(res.x, 0.0, None)
    return _rescale(h2)


def _peak_region(h, tol=0.999):
    Lf = _knots(h)
    mx = Lf.max()
    if mx <= 0:
        return 0, h.size - 1
    idx = np.flatnonzero(Lf >= tol * mx)
    lo = max(0, idx.min() - 1)
    hi = min(h.size - 1, idx.max())
    return lo, hi


def _homotopy(seed, betas, maxiter, deadline):
    cur = _rescale(seed.copy())
    cur_r = R_of(cur)
    for beta in betas:
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_sm(cur, beta, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            cur, cur_r = cand, r
    return cur, cur_r


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _prolong(h, m):
    n = h.size
    if m == n:
        return h.copy()
    c = np.concatenate(([0.0], np.cumsum(h)))
    x_old = np.linspace(0.0, 1.0, n + 1)
    x_new = np.linspace(0.0, 1.0, m + 1)
    c_new = np.interp(x_new, x_old, c)
    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _fresh(deadline):
    N0 = 64
    x = np.linspace(0, 1, N0)
    h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
    h = _rescale(h)
    cur_r = R_of(h)
    betas = (8, 32, 128, 512, 2048)
    N = N0
    while N <= 65536:
        if time.process_time() >= deadline - 6.0:
            break
        cand = _lbfgs_log(h, maxiter=400, deadline=deadline)
        r = R_of(cand)
        if r > cur_r:
            h, cur_r = cand, r
        cand, r = _homotopy(h, betas, 200, deadline)
        if r > cur_r:
            h, cur_r = cand, r
        if N >= 65536:
            break
        N = min(N * 2, 65536)
        h = _rescale(_prolong(h, N))
        cur_r = R_of(h)
    return h, cur_r


def _coarsen(h, k):
    n = h.size
    if n % k != 0:
        return None
    return h.reshape(n // k, k).sum(axis=1)


def _sharpen(h, deadline, rcur):
    cand = _lbfgs_log(h, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > rcur:
        return cand, r
    return h, rcur


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        best, best_r = _fresh(deadline)
        start_r = best_r

    if best.size < 65536:
        best = _rescale(_prolong(best, 65536))
        best_r = R_of(best)
        print("prolonged start to 65536: R=%.6f" % best_r)

    # ---- Step 1: coarsen by block-summing 4 adjacent heights ----
    coarse = None
    coarse_r = -1.0
    if best.size % 4 == 0:
        hc = _coarsen(best, 4)
        if hc is not None:
            rc = R_of(hc)
            if abs(rc - best_r) < 1e-9:
                coarse = hc
                coarse_r = rc
                print("coarsened to N=%d: R=%.9f (start %.9f)" % (hc.size, rc, best_r))
            else:
                print("coarsen mismatch %.9f vs %.9f" % (rc, best_r))

    # ---- Step 2: optimise hard on coarse grid (about 40% of remaining budget) ----
    if coarse is not None:
        coarse_deadline = min(deadline, time.process_time() + 0.40 * (deadline - time.process_time()))
        cc, cr = _sharpen(coarse, coarse_deadline, coarse_r)
        cc, cr = _homotopy(cc, (64, 256, 1024, 4096), 250, coarse_deadline)
        cc, cr = _polish(cc, coarse_deadline, cr,
                         fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        if cr > coarse_r:
            coarse, coarse_r = cc, cr
        print("coarse optimised: R=%.6f" % coarse_r)

        # ---- Step 3: re-detail back to N=65536 ----
        fine = np.repeat(coarse, 4) / 4.0
        fine_r = R_of(fine)
        print("re-detailed to N=%d: R=%.6f" % (fine.size, fine_r))
        if fine_r > best_r:
            best, best_r = fine, fine_r

    # ---- Continue alternating on the fine grid ----
    cand = _lbfgs_log(best, maxiter=600, deadline=deadline)
    r = R_of(cand)
    if r > best_r:
        best, best_r = cand, r
    print("after log polish R=%.6f" % best_r)

    it = 0
    while time.process_time() < deadline - 1.5:
        it += 1
        cand, r = _homotopy(best, (400, 1024, 2048, 4096, 8000), 250, deadline)
        if r > best_r:
            best, best_r = cand, r
        cand = _lbfgs_log(best, maxiter=300, deadline=deadline)
        r = R_of(cand)
        if r > best_r:
            best, best_r = cand, r
        cand, r = _polish(best, deadline, best_r,
                          fracs=(0.30, 0.15, 0.07, 0.03, 0.015), maxiter=400)
        if r > best_r:
            best, best_r = cand, r
        print("  alt#%d R=%.6f" % (it, best_r))

    print("best R=%.6f (start %.6f)" % (best_r, start_r))
    best = _rescale(best)

    if start_arr is not None and start_r >= best_r:
        return {"best": start_arr, "alternative": best}
    if start_arr is not None:
        return {"best": best, "alternative": start_arr}
    return best

