    if start_arr is not None:
        best = start_arr.copy()
        best_r = start_r
    else:
        # Fallback fresh seed: cosine bump at 64 steps, prolonged later.
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = (0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None)
