    h_new = np.diff(c_new)
    return np.clip(h_new, 0.0, None)


def _polish(h, deadline, rcur, fracs=(0.30, 0.15, 0.07, 0.03), maxiter=400):
    for frac in fracs:
        if time.process_time() >= deadline - 1.0:
            break
        lo, hi = _peak_region(h)
        span = hi - lo
        pad = max(8, int(span * frac))
        lo = max(0, lo - pad)
        hi = min(h.size - 1, hi + pad)
        free = np.arange(lo, hi + 1)
        cand = _lbfgs_block(h, free, maxiter=maxiter, deadline=deadline)
        r = R_of(cand)
        if r > rcur:
            h, rcur = cand, r
    return h, rcur


def _refine_line(h, r, deadline, tag, do_print=True):
    while time.process_time() < deadline - 1.5:
        cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r,
                           fracs=(0.40, 0.20, 0.10, 0.05, 0.02), maxiter=500)
        if r2 > r:
            h, r = cand, r2
        cand = _lbfgs_sm(h, 4096, maxiter=300, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        if do_print:
            print("  %s R=%.6f" % (tag, r))
    return h, r


def _smooth_tilt(h, slope, center=0.5):
    n = h.size
    x = np.linspace(0.0, 1.0, n)
    return _rescale(h * np.exp(slope * (x - center)))


def _refine_local(h, r, deadline, tag, do_print=False):
    for _ in range(3):
        if time.process_time() >= deadline - 1.0:
            break
        cand = _lbfgs_log(h, maxiter=200, deadline=deadline)
        r2 = R_of(cand)
        if r2 > r:
            h, r = cand, r2
        cand, r2 = _polish(h, deadline, r, fracs=(0.20, 0.08, 0.03), maxiter=300)
        if r2 > r:
            h, r = cand, r2
    if do_print:
        print("  %s R=%.6f" % (tag, r))
    return h, r


def _short_refine(h, r, deadline):
    """Short refine used after accepting a perturbation."""
    cand = _lbfgs_log(h, maxiter=150, deadline=deadline)
    r2 = R_of(cand)
    if r2 > r:
        h, r = cand, r2
    cand, r2 = _polish(h, deadline, r, fracs=(0.25, 0.10, 0.04), maxiter=300)
    if r2 > r:
        h, r = cand, r2
    return h, r


def _jitter_peak(h, sigma, rng):
    """Multiplicative log-normal jitter on the peak-feeding window [m-n, m]."""
    n = h.size
    Lf = _knots(h)
    m = int(np.argmax(Lf))
    lo = max(0, m - n)
    hi = min(n - 1, m)
    if hi < lo:
        return h.copy()
    idx = np.arange(lo, hi + 1)
    factor = np.exp(rng.normal(0.0, sigma, size=idx.size))
    h2 = h.copy()
    h2[idx] = h2[idx] * factor
    return _rescale(h2)


def _zero_revival(h):
    n = h.size
    h2 = h.copy()
    lo = n // 2
    hi = n
    zeros = np.flatnonzero(h2[lo:hi] == 0.0) + lo
    if zeros.size == 0:
        return h2
    # 256-step local mean
    k = 256
    c = np.concatenate(([0.0], np.cumsum(h2)))
    for z in zeros:
        a = max(0, z - k // 2)
        b = min(n, z + k // 2)
        mean = (c[b] - c[a]) / max(1, (b - a))
        h2[z] = 1e-3 * mean
    return _rescale(h2)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 2.0

    start_arr = None
    start_r = -1.0
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.ndim == 1 and s.size >= 1 and s.sum() > 0 and np.all(np.isfinite(s)):
            start_arr = _rescale(s.copy())
            start_r = R_of(start_arr)

    best = None
    best_r = -1.0

    if start_arr is not None:
        h = start_arr.copy()
        if h.size < 65536:
            h = _rescale(_prolong(h, 65536))
        r = R_of(h)
        print("start base R=%.6f N=%d" % (r, h.size))

        # Phase 1: capped refine of the start (12 s CPU).
        cap = time.process_time() + 12.0
        cap_deadline = min(cap, deadline - 3.0)
        h, r = _refine_line(h, r, cap_deadline, "start-refine")
        best, best_r = h, r
        print("start-refined R=%.6f (was %.6f)" % (best_r, start_r))

        # Phase 2: perturbation bank on the incumbent.
        tilts = [0.05, -0.05, 0.15, -0.15, 0.30, -0.30, 0.50, -0.50]
        sigmas = [0.05, 0.10, 0.20]
        cycle = 0
        while time.process_time() < deadline - 2.0:
            accepted = False
            # (a) tilts
            for s in tilts:
                if time.process_time() >= deadline - 2.0:
                    break
                cand = _smooth_tilt(best, s)
                cand, r2 = _short_refine(cand, R_of(cand), deadline - 1.0)
                if r2 > best_r + 1e-12:
                    best, best_r = cand, r2
                    accepted = True
                    print("  tilt %.2f accepted R=%.6f" % (s, best_r))
                    break
            if accepted:
                # Spend up to 6 s refining.
                rd = min(time.process_time() + 6.0, deadline - 2.0)
                best, best_r = _refine_line(best, best_r, rd,
                                            "post-tilt", do_print=False)
                print("  post-tilt R=%.6f" % best_r)
                cycle += 1
                continue
            # (b) jitter
            for sigma in sigmas:
                if time.process_time() >= deadline - 2.0:
                    break
                rng = np.random.RandomState(cycle * 1000 + int(sigma * 1000))
                cand = _jitter_peak(best, sigma, rng)
                cand, r2 = _short_refine(cand, R_of(cand), deadline - 1.0)
                if r2 > best_r + 1e-12:
                    best, best_r = cand, r2
                    accepted = True
                    print("  jitter %.2f accepted R=%.6f" % (sigma, best_r))
                    break
            if accepted:
                rd = min(time.process_time() + 6.0, deadline - 2.0)
                best, best_r = _refine_line(best, best_r, rd,
                                            "post-jitter", do_print=False)
                print("  post-jitter R=%.6f" % best_r)
                cycle += 1
                continue
            # (c) zero revival
            if time.process_time() < deadline - 2.0:
                cand = _zero_revival(best)
                cand, r2 = _short_refine(cand, R_of(cand), deadline - 1.0)
                if r2 > best_r + 1e-12:
                    best, best_r = cand, r2
                    accepted = True
                    print("  zero-revival accepted R=%.6f" % best_r)
                    rd = min(time.process_time() + 6.0, deadline - 2.0)
                    best, best_r = _refine_line(best, best_r, rd,
                                                "post-revival", do_print=False)
                    print("  post-revival R=%.6f" % best_r)
            cycle += 1
            if not accepted:
                # Avoid infinite tight loop; small progress print occasionally.
                if cycle % 3 == 0:
                    print("  cycle %d no acceptance, R=%.6f" % (cycle, best_r))
    else:
        # No start: build a fresh construction from scratch.
        N0 = 64
        x = np.linspace(0, 1, N0)
        h = _rescale((0.5 + 0.5 * np.cos(2 * np.pi * (x - 0.5))).clip(1e-3, None))
        cur_r = R_of(h)
        betas = (8, 32, 128, 512, 2048)
        N = N0
        while N <= 65536 and time.process_time() < deadline - 3.0:
            cand = _lbfgs_log(h, maxiter=300, deadline=deadline)
            rr = R_of(cand)
            if rr > cur_r:
                h, cur_r = cand, rr
            for beta in betas:
                if time.process_time() >= deadline - 2.0:
                    break
                cand = _lbfgs_sm(h, beta, maxiter=150, deadline=deadline)
                rr = R_of(cand)
                if rr > cur_r:
                    h, cur_r = cand, rr
            if N >= 65536:
                break
            N = min(N * 2, 65536)
            h = _rescale(_prolong(h, N))
            cur_r = R_of(h)
        h, cur_r = _refine_line(h, cur_r, deadline - 1.0, "fresh")
        best, best_r = h, cur_r
        print("fresh R=%.6f" % best_r)

    print("best R=%.6f (start %.6f)" % (best_r, start_r))

    if start_arr is not None:
        if best_r > start_r + 1e-12:
            return {"best": _rescale(best), "alternative": _rescale(start_arr)}
        if best is not None and not np.array_equal(best, start_arr) and best_r > 0:
            return {"best": _rescale(start_arr), "alternative": _rescale(best)}
        return _rescale(start_arr)

    return _rescale(best)
